package com.harbourmaster.tools;

import com.harbourmaster.model.Port;
import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.coords.WorldPoint;

final class CharterDataGenerator {
    private CharterDataGenerator() {}

    static void generate() throws IOException, InterruptedException {
        String routes = parse(download("Charter_ship"), download("Template:Charter_ship_fares"));
        Files.writeString(
                Path.of("src", "main", "resources", "com", "harbourmaster", "charters.tsv"),
                routes,
                StandardCharsets.UTF_8);
        System.out.println("Generated charter routes from the wiki");
    }

    private static String download(String page) throws IOException, InterruptedException {
        HttpRequest request = HttpRequest.newBuilder(
                        URI.create("https://oldschool.runescape.wiki/w/" + page + "?action=raw"))
                .header("User-Agent", "Harbourmaster route data generator")
                .timeout(Duration.ofSeconds(30))
                .GET()
                .build();
        HttpResponse<String> response =
                HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
        if (response.statusCode() != 200) {
            throw new IOException("Wiki charter download returned HTTP " + response.statusCode() + " for " + page);
        }
        return response.body();
    }

    private static String parse(String locationSource, String fareSource) {
        Map<String, Port> ports = new HashMap<>();
        for (Port port : Port.values()) {
            ports.put(port.name, port);
        }
        Map<String, WorldPoint> locations = new HashMap<>();
        Matcher location = Pattern.compile("^\\|x:(\\d+),y:(\\d+),title:\\[\\[(.+?)\\]\\]", Pattern.MULTILINE)
                .matcher(locationSource);
        while (location.find()) {
            locations.put(
                    location.group(3),
                    new WorldPoint(Integer.parseInt(location.group(1)), Integer.parseInt(location.group(2)), 0));
        }
        List<String> destinations = new ArrayList<>();
        Matcher destination =
                Pattern.compile("^!\\[\\[(.+?)\\]\\]$", Pattern.MULTILINE).matcher(fareSource);
        while (destination.find()) {
            destinations.add(destination.group(1));
        }

        StringBuilder routes =
                new StringBuilder("# Coordinates use the wiki charter map markers for walking estimates.\n"
                        + "# origin destination coins origin_x origin_y arrival_x arrival_y\n");
        Set<String> origins = new HashSet<>();
        Matcher row = Pattern.compile(
                        "^! style=\"text-align:right;\" \\|\\[\\[(.+?)\\]\\]\\R((?:\\|(?!-)[^\\r\\n]*\\R)+)",
                        Pattern.MULTILINE)
                .matcher(fareSource);
        while (row.find()) {
            origins.add(row.group(1));
            String[] prices = row.group(2).strip().split("\\R");
            if (prices.length != destinations.size()) {
                throw new IllegalStateException("Incomplete wiki charter fares for " + row.group(1));
            }
            Port from = ports.get(row.group(1));
            if (from == null) {
                continue;
            }
            WorldPoint origin = locations.get(from.name);
            for (int index = 0; index < destinations.size(); index++) {
                Port to = ports.get(destinations.get(index));
                String price = prices[index].substring(1);
                if (to == null || "{{NA}}".equals(price)) {
                    continue;
                }
                WorldPoint arrival = locations.get(to.name);
                routes.append(String.format(
                        Locale.ROOT,
                        "%s\t%s\t%d\t%d\t%d\t%d\t%d\n",
                        from.name(),
                        to.name(),
                        Integer.parseInt(price.replace(",", "")),
                        origin.getX(),
                        origin.getY(),
                        arrival.getX(),
                        arrival.getY()));
            }
        }
        if (destinations.isEmpty() || !origins.equals(new HashSet<>(destinations))) {
            throw new IllegalStateException("Incomplete wiki charter fare table");
        }
        return routes.toString();
    }
}

package com.harbourmaster.tools;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.annotations.SerializedName;
import com.harbourmaster.data.BoatSize;
import com.harbourmaster.data.SailingObstacles;
import com.harbourmaster.data.SailingPathfinder;
import com.harbourmaster.data.SailingShortcut;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteLeg;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Instant;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.Comparator;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.zip.ZipEntry;
import java.util.zip.ZipInputStream;
import net.runelite.api.IndexDataBase;
import net.runelite.api.coords.WorldPoint;
import net.runelite.cache.IndexType;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Store;

public final class RouteDataGenerator {
    private static final Gson GSON = new GsonBuilder().setPrettyPrinting().create();
    private static final String OPENRS2 = "https://archive.openrs2.org";
    private static final Path WORKING_DIRECTORY = Path.of("build", "route-generation");

    private RouteDataGenerator() {}

    public static void main(String[] arguments) throws Exception {
        if (arguments.length == 1 && "--latest-cache-id".equals(arguments[0])) {
            System.out.println(cache(null).id);
            return;
        }
        String cacheId = arguments.length == 0 || arguments[0].isEmpty() ? null : arguments[0];
        BoatSize boatSize = arguments.length < 2 || arguments[1].isEmpty() ? null : BoatSize.valueOf(arguments[1]);
        CharterDataGenerator.generate();
        CacheRecord cache = cache(cacheId);
        Path cacheDirectory = download(cache);
        System.out.println("Using Old School live cache " + cache.id + " from " + cache.timestamp);
        generate(cacheDirectory, cache.id, boatSize);
    }

    private static CacheRecord cache(String cacheId) throws IOException, InterruptedException {
        HttpClient http = HttpClient.newHttpClient();
        HttpRequest request = HttpRequest.newBuilder(URI.create(OPENRS2 + "/caches.json"))
                .GET()
                .build();
        CacheRecord[] records;
        try (InputStream response =
                http.send(request, HttpResponse.BodyHandlers.ofInputStream()).body()) {
            records = GSON.fromJson(new InputStreamReader(response, StandardCharsets.UTF_8), CacheRecord[].class);
        }
        if (cacheId != null) {
            for (CacheRecord record : records) {
                if (cacheId.equals(String.valueOf(record.id))) {
                    requireComplete(record);
                    return record;
                }
            }
            throw new IllegalArgumentException("OpenRS2 has no Old School live cache " + cacheId);
        }
        return java.util.Arrays.stream(records)
                .filter(record -> "oldschool".equals(record.game)
                        && "live".equals(record.environment)
                        && "en".equals(record.language)
                        && record.isComplete())
                .max(Comparator.comparing(record -> Instant.parse(record.timestamp)))
                .orElseThrow(() -> new IllegalStateException("OpenRS2 has no complete English live cache"));
    }

    private static void requireComplete(CacheRecord record) {
        if (!"oldschool".equals(record.game)
                || !"live".equals(record.environment)
                || !"en".equals(record.language)
                || !record.isComplete()) {
            throw new IllegalArgumentException("OpenRS2 cache " + record.id + " is not a complete English live cache");
        }
    }

    private static Path download(CacheRecord record) throws IOException, InterruptedException {
        Path directory = WORKING_DIRECTORY.resolve(String.valueOf(record.id));
        Path archive = directory.resolve("disk.zip");
        Path cacheDirectory = directory.resolve("cache");
        Files.createDirectories(directory);
        if (!Files.exists(cacheDirectory.resolve("main_file_cache.dat2"))) {
            if (!Files.exists(archive)) {
                Path partial = directory.resolve("disk.zip.part");
                HttpRequest request = HttpRequest.newBuilder(
                                URI.create(OPENRS2 + "/caches/runescape/" + record.id + "/disk.zip"))
                        .GET()
                        .build();
                HttpResponse<Path> response =
                        HttpClient.newHttpClient().send(request, HttpResponse.BodyHandlers.ofFile(partial));
                if (response.statusCode() != 200) {
                    throw new IOException("OpenRS2 cache download returned HTTP " + response.statusCode());
                }
                Files.move(partial, archive, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
            }
            extract(archive, directory);
        }
        return cacheDirectory;
    }

    private static void extract(Path archive, Path directory) throws IOException {
        Path root = directory.toAbsolutePath().normalize();
        try (InputStream input = Files.newInputStream(archive);
                ZipInputStream zip = new ZipInputStream(input)) {
            ZipEntry entry;
            while ((entry = zip.getNextEntry()) != null) {
                Path target = root.resolve(entry.getName()).normalize();
                if (!target.startsWith(root)) {
                    throw new IOException("Invalid path in OpenRS2 cache archive: " + entry.getName());
                }
                if (entry.isDirectory()) {
                    Files.createDirectories(target);
                    continue;
                }
                Files.createDirectories(target.getParent());
                try (OutputStream output = Files.newOutputStream(target)) {
                    zip.transferTo(output);
                }
            }
        }
    }

    private static void generate(Path cacheDirectory, long cacheId, BoatSize selectedBoatSize) throws Exception {
        long startedAt = System.nanoTime();
        IndexDataBase terrain;
        Map<Integer, BitSet> obstacleRegions;
        try (Store store = new Store(cacheDirectory.toFile())) {
            store.load();
            obstacleRegions = SailingObstacleGenerator.generate(store);
            terrain = new CacheTerrainIndexDataBase(store, store.getIndex(IndexType.MAPS));
        }
        SailingObstacles obstacles = new SailingObstacles(obstacleRegions);
        SailingPathfinder.prepareMasks();
        ExecutorService workers = Executors.newFixedThreadPool(selectedBoatSize == null ? BoatSize.values().length : 1);
        Map<BoatSize, Future<RouteFile>> generated = new EnumMap<>(BoatSize.class);
        try {
            for (BoatSize boatSize : BoatSize.values()) {
                if (selectedBoatSize != null && selectedBoatSize != boatSize) {
                    continue;
                }
                generated.put(boatSize, workers.submit(() -> generate(terrain, obstacles, boatSize, cacheId)));
            }
            Map<BoatSize, RouteFile> completed = new EnumMap<>(BoatSize.class);
            for (Map.Entry<BoatSize, Future<RouteFile>> entry : generated.entrySet()) {
                completed.put(entry.getKey(), entry.getValue().get());
            }
            SailingObstacleGenerator.write(obstacleRegions);
            for (Map.Entry<BoatSize, RouteFile> entry : completed.entrySet()) {
                write(entry.getKey(), entry.getValue());
            }
        } finally {
            workers.shutdownNow();
        }
        System.out.printf(
                "Generated sailing routes in %.1f minutes%n", (System.nanoTime() - startedAt) / 60_000_000_000.0);
    }

    private static RouteFile generate(
            IndexDataBase terrain, SailingObstacles obstacles, BoatSize boatSize, long cacheId) {
        SailingPathfinder pathfinder = new SailingPathfinder(terrain, 1, obstacles);
        List<RouteEntry> routes = new ArrayList<>();
        for (int toIndex = 1; toIndex < Port.values().length; toIndex++) {
            Port to = Port.values()[toIndex];
            pathfinder.prepareDestination(to.navigationLocation, boatSize);
            for (int fromIndex = 0; fromIndex < toIndex; fromIndex++) {
                Port from = Port.values()[fromIndex];
                if (Thread.currentThread().isInterrupted()) {
                    throw new IllegalStateException("Sailing route generation interrupted");
                }
                RouteLeg route = pathfinder
                        .route(from.navigationLocation, to.navigationLocation, boatSize)
                        .map(result -> pathfinder.refineRoute(result, boatSize))
                        .map(result -> new RouteLeg(from, to, result.distance, result.points))
                        .orElse(null);
                routes.add(new RouteEntry(from, to, route));
                System.out.printf(
                        "%s: %s to %s, %s%n",
                        boatSize,
                        from.name,
                        to.name,
                        route == null ? "unreachable" : String.format("%.2f tiles", route.distance));
            }
        }
        routes.sort(Comparator.comparingInt(
                        (RouteEntry route) -> Port.valueOf(route.from).ordinal())
                .thenComparingInt(route -> Port.valueOf(route.to).ordinal()));
        RouteFile file = new RouteFile();
        file.formatVersion = 2;
        file.cacheId = cacheId;
        file.boatSize = boatSize.name();
        file.routes = routes;
        file.portalRoutes = generatePortals(pathfinder, boatSize);
        return file;
    }

    private static List<PortalEntry> generatePortals(SailingPathfinder pathfinder, BoatSize boatSize) {
        List<PortalEntry> routes = new ArrayList<>();
        for (SailingShortcut shortcut : SailingShortcut.GWENITH) {
            WorldPoint entrance = shortcut.approach(boatSize);
            pathfinder.prepareDestination(entrance, boatSize);
            for (Port port : Port.values()) {
                RouteLeg route = pathfinder
                        .route(port.navigationLocation, entrance, boatSize, -1, shortcut.entryHeading)
                        .orElse(null);
                routes.add(new PortalEntry(port.navigationLocation, entrance, -1, shortcut.entryHeading, route));
                System.out.printf("%s: %s to %s, %s%n", boatSize, port.name, shortcut.name, route != null);
            }
        }
        for (Port port : Port.values()) {
            pathfinder.prepareDestination(port.navigationLocation, boatSize);
            for (SailingShortcut shortcut : SailingShortcut.GWENITH) {
                WorldPoint exit = shortcut.departure(boatSize);
                RouteLeg route = pathfinder
                        .route(exit, port.navigationLocation, boatSize, shortcut.exitHeading, -1)
                        .orElse(null);
                routes.add(new PortalEntry(exit, port.navigationLocation, shortcut.exitHeading, -1, route));
                System.out.printf("%s: %s to %s, %s%n", boatSize, shortcut.name, port.name, route != null);
            }
        }
        return routes;
    }

    private static final class CacheTerrainIndexDataBase implements IndexDataBase {
        private final Map<Integer, byte[]> regions = new HashMap<>();

        private CacheTerrainIndexDataBase(Store store, Index index) throws IOException {
            for (Archive archive : index.getArchives()) {
                if (!SailingPathfinder.includesRegion(archive.getArchiveId())) {
                    continue;
                }
                ArchiveFiles files = archive.getFiles(store.getStorage().loadArchive(archive));
                regions.put(archive.getArchiveId(), files.findFile(0).getContents());
            }
        }

        @Override
        public boolean isOverlayOutdated() {
            return false;
        }

        @Override
        public int[] getFileIds(int regionId) {
            return regions.containsKey(regionId) ? new int[] {0} : new int[0];
        }

        @Override
        public byte[] loadData(int regionId, int fileId) {
            return fileId == 0 ? regions.get(regionId) : null;
        }
    }

    private static void write(BoatSize boatSize, RouteFile file) throws IOException {
        Path output = Path.of(
                "src",
                "main",
                "resources",
                "com",
                "harbourmaster",
                "routes",
                boatSize.name().toLowerCase(Locale.ROOT) + ".json");
        Files.createDirectories(output.getParent());
        Files.writeString(output, GSON.toJson(file) + System.lineSeparator(), StandardCharsets.UTF_8);
    }

    private static final class CacheRecord {
        private long id;
        private String game;
        private String environment;
        private String language;
        private String timestamp;
        private Integer valid_indexes;
        private Integer indexes;
        private Integer valid_groups;
        private Integer groups;

        @SerializedName("disk_store_valid")
        private Boolean disk_store_valid;

        private boolean isComplete() {
            return Boolean.TRUE.equals(disk_store_valid)
                    && valid_indexes != null
                    && valid_indexes.equals(indexes)
                    && valid_groups != null
                    && valid_groups.equals(groups)
                    && timestamp != null;
        }
    }

    private static final class RouteFile {
        private int formatVersion;
        private long cacheId;
        private String boatSize;
        private List<RouteEntry> routes;
        private List<PortalEntry> portalRoutes;
    }

    private static final class PortalEntry {
        private final int[] from;
        private final int[] to;
        private final int departure;
        private final int arrival;
        private final Double distance;
        private final int[][] points;

        private PortalEntry(WorldPoint from, WorldPoint to, int departure, int arrival, RouteLeg route) {
            this.from = new int[] {from.getX(), from.getY()};
            this.to = new int[] {to.getX(), to.getY()};
            this.departure = departure;
            this.arrival = arrival;
            distance = route == null ? null : route.distance;
            points = route == null
                    ? new int[0][]
                    : route.points.stream()
                            .map(point -> new int[] {point.getX(), point.getY()})
                            .toArray(int[][]::new);
        }
    }

    private static final class RouteEntry {
        private String from;
        private String to;
        private Double distance;
        private int[][] points;

        private RouteEntry(Port from, Port to, RouteLeg route) {
            this.from = from.name();
            this.to = to.name();
            if (route == null) {
                this.points = new int[0][];
                return;
            }
            distance = route.distance;
            points = new int[route.points.size()][2];
            for (int index = 0; index < route.points.size(); index++) {
                WorldPoint point = route.points.get(index);
                points[index] = new int[] {point.getX(), point.getY()};
            }
        }
    }
}

package com.harbourmaster.tools;

import com.harbourmaster.data.SailingPathfinder;
import java.io.DataOutputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.BitSet;
import java.util.Map;
import java.util.TreeMap;
import java.util.zip.GZIPOutputStream;
import net.runelite.cache.ConfigType;
import net.runelite.cache.IndexType;
import net.runelite.cache.definitions.ObjectDefinition;
import net.runelite.cache.definitions.loaders.LocationsLoader;
import net.runelite.cache.definitions.loaders.ObjectLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.Store;
import net.runelite.cache.region.Location;

final class SailingObstacleGenerator {
    private SailingObstacleGenerator() {}

    static Map<Integer, BitSet> generate(Store store) throws IOException {
        if (store.getIndex(IndexType.MAPS).isNamed()) {
            throw new IllegalArgumentException("Sailing obstacles require the current unencrypted map cache format");
        }
        Archive archive = store.getIndex(IndexType.CONFIGS).getArchive(ConfigType.OBJECT.getId());
        ArchiveFiles files = archive.getFiles(store.getStorage().loadArchive(archive));
        Map<Integer, ObjectDefinition> definitions = new TreeMap<>();
        for (var file : files.getFiles()) {
            definitions.put(file.getFileId(), new ObjectLoader().load(file.getFileId(), file.getContents()));
        }
        Map<Integer, BitSet> regions = new TreeMap<>();
        for (Archive region : store.getIndex(IndexType.MAPS).getArchives()) {
            if (!SailingPathfinder.includesRegion(region.getArchiveId())) {
                continue;
            }
            int regionX = region.getArchiveId() >> 8;
            int regionY = region.getArchiveId() & 255;
            ArchiveFiles map = region.getFiles(store.getStorage().loadArchive(region));
            for (Location location : new LocationsLoader()
                    .load(regionX, regionY, map.findFile(1).getContents())
                    .getLocations()) {
                if (location.getPosition().getZ() != 0) {
                    continue;
                }
                ObjectDefinition definition = definitions.get(location.getId());
                int type = location.getType();
                if (definition.getInteractType() == 0
                        || definition.isHollow()
                        || (type >= 4 && type <= 8)
                        || (type == 22 && definition.getInteractType() != 1)) {
                    continue;
                }
                int x = regionX * 64 + location.getPosition().getX();
                int y = regionY * 64 + location.getPosition().getY();
                int rotation = location.getOrientation();
                if (type <= 3) {
                    block(regions, x, y);
                    int[] horizontal = {-1, 0, 1, 0};
                    int[] vertical = {0, 1, 0, -1};
                    block(regions, x + horizontal[rotation], y + vertical[rotation]);
                    if (type != 0) {
                        int next = (rotation + 1) % 4;
                        block(regions, x + horizontal[next], y + vertical[next]);
                    }
                    continue;
                }
                int width = rotation % 2 == 0 ? definition.getSizeX() : definition.getSizeY();
                int height = rotation % 2 == 0 ? definition.getSizeY() : definition.getSizeX();
                for (int horizontal = 0; horizontal < width; horizontal++) {
                    for (int vertical = 0; vertical < height; vertical++) {
                        block(regions, x + horizontal, y + vertical);
                    }
                }
            }
        }
        System.out.println("Generated object obstacles for " + regions.size() + " regions");
        return regions;
    }

    static void write(Map<Integer, BitSet> regions) throws IOException {
        Path output = Path.of("src/main/resources/com/harbourmaster/routes/obstacles.dat.gz");
        try (DataOutputStream stream = new DataOutputStream(new GZIPOutputStream(Files.newOutputStream(output)))) {
            stream.writeInt(regions.size());
            for (Map.Entry<Integer, BitSet> region : regions.entrySet()) {
                stream.writeShort(region.getKey());
                stream.write(Arrays.copyOf(region.getValue().toByteArray(), 512));
            }
        }
    }

    private static void block(Map<Integer, BitSet> regions, int x, int y) {
        regions.computeIfAbsent((x >> 6) * 256 + (y >> 6), ignored -> new BitSet(4096))
                .set((x & 63) * 64 + (y & 63));
    }
}

package com.harbourmaster;

import com.harbourmaster.model.BoatFocus;
import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("harbourmaster")
public interface HarbourmasterConfig extends Config {
    @ConfigSection(name = "Noticeboard", description = "Noticeboard settings", position = 0)
    String noticeboard = "noticeboard";

    @ConfigItem(
            keyName = "highlightNoticeboards",
            name = "Highlight noticeboards",
            description = "Highlight nearby Sailing task boards.",
            section = noticeboard,
            position = 0)
    default boolean highlightNoticeboards() {
        return true;
    }

    @ConfigItem(
            keyName = "subdueFullBoards",
            name = "Subdue full boards",
            description = "Use a subdued outline when no task slots are free.",
            section = noticeboard,
            position = 1)
    default boolean subdueFullBoards() {
        return true;
    }

    @ConfigItem(
            keyName = "rankOffers",
            name = "Highlight recommended offers",
            description = "Highlight courier offers selected for the best courier XP per hour.",
            section = noticeboard,
            position = 2)
    default boolean rankOffers() {
        return true;
    }

    @Alpha
    @ConfigItem(
            keyName = "bestOfferColor",
            name = "Recommended offer colour",
            description = "Colour for recommended courier jobs and nearby task boards.",
            section = noticeboard,
            position = 3)
    default Color bestOfferColor() {
        return new Color(70, 225, 175);
    }

    @ConfigSection(name = "Route", description = "Route settings", position = 1)
    String route = "route";

    @ConfigItem(
            keyName = "enableOptimizer",
            name = "Enable route optimiser",
            description = "Find an efficient sailing route through your courier plan.",
            section = route,
            position = 0)
    default boolean enableOptimizer() {
        return true;
    }

    @ConfigItem(
            keyName = "showRouteOverlay",
            name = "Show route status",
            description = "Show the next destination and action while sailing.",
            section = route,
            position = 1)
    default boolean showRouteOverlay() {
        return true;
    }

    @ConfigItem(
            keyName = "showWorldMap",
            name = "Show world map route",
            description = "Draw the route on the world map.",
            section = route,
            position = 2)
    default boolean showWorldMap() {
        return true;
    }

    @ConfigItem(
            keyName = "showWorldRoute",
            name = "Show in-world route",
            description = "Draw the current sailing leg in the world.",
            section = route,
            position = 3)
    default boolean showWorldRoute() {
        return true;
    }

    @ConfigItem(
            keyName = "showMinimap",
            name = "Show minimap route",
            description = "Draw the current sailing leg on the minimap.",
            section = route,
            position = 4)
    default boolean showMinimap() {
        return true;
    }

    @ConfigItem(
            keyName = "showCompleteRoute",
            name = "Show complete route",
            description = "Also draw future legs in a subdued colour.",
            section = route,
            position = 5)
    default boolean showCompleteRoute() {
        return false;
    }

    @Alpha
    @ConfigItem(
            keyName = "activeRouteColor",
            name = "Active route colour",
            description = "Colour of the current sailing leg.",
            section = route,
