package com.harbourmaster.data;

import java.util.List;
import net.runelite.api.coords.WorldPoint;

public final class SailingShortcut {
    // Portal centres checked against OpenRS2 cache 2720. Exit positions from
    // https://github.com/NathanVegetable/barracuda-trial (GwenithGlideRoutes).
    // These directed exits also work outside a trial. Headings use east = 0, north = 2.
    public static final List<SailingShortcut> GWENITH = List.of(
            new SailingShortcut("Black portal", new WorldPoint(2105, 3424, 0), 6, new WorldPoint(2198, 3584, 0), 4),
            new SailingShortcut(
                    "Light blue portal", new WorldPoint(2142, 3582, 0), 4, new WorldPoint(2137, 3253, 0), 2));

    public final String name;
    public final WorldPoint entrance;
    public final int entryHeading;
    public final WorldPoint exit;
    public final int exitHeading;

    public SailingShortcut(String name, WorldPoint entrance, int entryHeading, WorldPoint exit, int exitHeading) {
        this.name = name;
        this.entrance = entrance;
        this.entryHeading = entryHeading;
        this.exit = exit;
        this.exitHeading = exitHeading;
    }

    public WorldPoint approach(BoatSize boatSize) {
        return offset(entrance, entryHeading, -(boatSize.length / 2 + 3));
    }

    public WorldPoint departure(BoatSize boatSize) {
        return offset(exit, exitHeading, boatSize.length / 2 + 3);
    }

    private static WorldPoint offset(WorldPoint point, int heading, int tiles) {
        int[] horizontal = {1, 1, 0, -1, -1, -1, 0, 1};
        int[] vertical = {0, 1, 1, 1, 0, -1, -1, -1};
        return new WorldPoint(point.getX() + horizontal[heading] * tiles, point.getY() + vertical[heading] * tiles, 0);
    }
}

package com.harbourmaster.data;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public final class TaskRewards {
    private final Map<Integer, Integer> experience = new HashMap<>();

    public TaskRewards() {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                Objects.requireNonNull(TaskRewards.class.getResourceAsStream("/com/harbourmaster/task-rewards.tsv")),
                StandardCharsets.UTF_8))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("#")) {
                    continue;
                }
                String[] fields = line.split("\t");
                experience.put(Integer.parseInt(fields[0]), Integer.parseInt(fields[1]));
            }
        } catch (IOException exception) {
            throw new UncheckedIOException(exception);
        }
    }

    public int forRow(int databaseRow) {
        return experience.getOrDefault(databaseRow, -1);
    }
}

package com.harbourmaster.model;

public final class ActiveTask {
    public final int slot;
    public final int taskId;
    public final CourierTask definition;
    public final int cargoTaken;
    public final int cargoDelivered;

    public ActiveTask(int slot, int taskId, CourierTask definition, int cargoTaken, int cargoDelivered) {
        this.slot = slot;
        this.taskId = taskId;
        this.definition = definition;
        this.cargoTaken = cargoTaken;
        this.cargoDelivered = cargoDelivered;
    }

    public int pickupRemaining() {
        return Math.max(0, definition.quantity - cargoTaken);
    }

    public int deliveryRemaining() {
        return Math.max(0, definition.quantity - cargoDelivered);
    }

    public int carried() {
        return Math.max(0, cargoTaken - cargoDelivered);
    }

    public boolean isFinished() {
        return definition != null && deliveryRemaining() == 0;
    }

    @Override
    public boolean equals(Object other) {
        if (!(other instanceof ActiveTask)) {
            return false;
        }
        ActiveTask task = (ActiveTask) other;
        return slot == task.slot
                && taskId == task.taskId
                && definition == task.definition
                && cargoTaken == task.cargoTaken
                && cargoDelivered == task.cargoDelivered;
    }

    @Override
    public int hashCode() {
        return java.util.Objects.hash(slot, taskId, definition, cargoTaken, cargoDelivered);
    }
}

