package com.harbourmaster.model;

import java.util.ArrayList;
import java.util.List;

public final class DockChecklist {
    public final Port port;
    public final List<RouteEvent> actions;
    public final boolean claimRewards;

    private DockChecklist(Port port, List<RouteEvent> actions, boolean claimRewards) {
        this.port = port;
        this.actions = List.copyOf(actions);
        this.claimRewards = claimRewards;
    }

    public static DockChecklist at(Port port, List<ActiveTask> tasks) {
        List<RouteEvent> actions = new ArrayList<>();
        if (port != null) {
            for (ActiveTask active : tasks) {
                if (active.definition == null || active.isFinished()) {
                    continue;
                }
                CourierTask task = active.definition;
                if (task.delivery == port && active.carried() > 0) {
                    actions.add(new RouteEvent(
                            active.slot,
                            task,
                            RouteEvent.Action.DELIVER,
                            port,
                            Math.min(active.carried(), active.deliveryRemaining())));
                }
                if (task.pickup == port && active.pickupRemaining() > 0) {
                    actions.add(new RouteEvent(
                            active.slot, task, RouteEvent.Action.PICKUP, port, active.pickupRemaining()));
                }
            }
        }
        actions.sort(java.util.Comparator.comparing(event -> event.action == RouteEvent.Action.PICKUP));
        return new DockChecklist(
                port,
                actions,
                tasks.stream().anyMatch(ActiveTask::isFinished)
                        && actions.stream().noneMatch(event -> event.action == RouteEvent.Action.DELIVER));
    }

    public boolean hasUnload() {
        return actions.stream().anyMatch(event -> event.action == RouteEvent.Action.DELIVER);
    }

    public DockChecklist follow(RoutePlan route) {
        if (!route.available || route.stops.isEmpty()) {
            return this;
        }
        return new DockChecklist(port, route.stops.get(0).port == port ? route.nextActions() : List.of(), claimRewards);
    }

    public DockChecklist withoutActions() {
        return new DockChecklist(port, List.of(), claimRewards);
    }

    public boolean hasAcceptance() {
        return actions.stream().anyMatch(event -> event.action == RouteEvent.Action.ACCEPT);
    }

    public boolean unloads(int itemId) {
        return actions.stream()
                .anyMatch(event -> event.action == RouteEvent.Action.DELIVER && event.task.itemId == itemId);
    }
}

package com.harbourmaster.model;

public enum DockGuidance {
    NONE(Target.NONE, "", "", false),
    DEPOSIT_CARGO(Target.CARGO_HOLD, "Deposit task cargo", "Put the carried crate in the cargo hold", false),
    BOARD_TO_DEPOSIT(Target.GANGPLANK, "Board to deposit cargo", "Put the carried crate in the cargo hold", false),
    TAKE_DELIVERY_CARGO(
            Target.CARGO_HOLD, "Take delivery crates", "Collect the highlighted cargo before going ashore", true),
    BOARD_TO_FETCH(Target.GANGPLANK, "Board to fetch crates", "Collect the remaining delivery cargo", true),
    LEAVE_TO_DELIVER(Target.GANGPLANK, "Go ashore to deliver cargo", "Take the carried crate to the ledger", true),
    DELIVER(Target.LEDGER, "Deliver task cargo", "Use the ledger to deliver the carried crate", true),
    LEAVE_TO_CLAIM(Target.GANGPLANK, "Go ashore to claim rewards", "Claim completed tasks from the port master", true),
    CLAIM_REWARDS(
            Target.PORT_MASTER,
            "Claim rewards from the port master",
            "Right click the port master and choose Claim rewards",
            true),
    LEAVE_TO_CHECK_BOARD(
            Target.GANGPLANK, "Go ashore to check offers", "Open the noticeboard before continuing", false),
    CHECK_BOARD(Target.NOTICEBOARD, "Check the noticeboard", "Accept the highlighted courier offers", false),
    LEAVE_TO_PICKUP(Target.GANGPLANK, "Go ashore to collect cargo", "Use the ledger to collect task cargo", false),
    PICKUP(Target.LEDGER, "Collect task cargo", "Use the ledger, then deposit cargo aboard", false),
    BOARD_TO_SAIL(Target.GANGPLANK, "Board to sail", "Continue along the route to the next port", false);

    public enum Target {
        NONE,
        CARGO_HOLD,
        GANGPLANK,
        NOTICEBOARD,
        LEDGER,
        PORT_MASTER
    }

    public final Target target;
    public final String instruction;
    public final String detail;
    public final boolean unload;

    DockGuidance(Target target, String instruction, String detail, boolean unload) {
        this.target = target;
        this.instruction = instruction;
        this.detail = detail;
        this.unload = unload;
    }

    public static DockGuidance next(
            HarbourmasterSnapshot state,
            boolean aboard,
            boolean carryingDelivery,
            boolean checkNoticeboard,
            boolean unloadCargo,
            boolean atSea) {
        if (state.depositCargo) {
            return aboard ? DEPOSIT_CARGO : BOARD_TO_DEPOSIT;
        }
        if (state.dock.port == null || atSea && state.dock.port != state.nextPort()) {
            return NONE;
        }
        if (carryingDelivery) {
            return aboard ? LEAVE_TO_DELIVER : DELIVER;
        }
        if (unloadCargo) {
            return TAKE_DELIVERY_CARGO;
        }
        if (state.dock.claimRewards) {
            return aboard ? LEAVE_TO_CLAIM : CLAIM_REWARDS;
        }
        if (checkNoticeboard || state.dock.hasAcceptance()) {
            return aboard ? LEAVE_TO_CHECK_BOARD : CHECK_BOARD;
        }
        if (state.dock.hasUnload()) {
            return aboard ? TAKE_DELIVERY_CARGO : BOARD_TO_FETCH;
        }
        if (state.dock.actions.stream().anyMatch(event -> event.action == RouteEvent.Action.PICKUP)) {
            return aboard ? LEAVE_TO_PICKUP : PICKUP;
        }
        if (state.sailingNext() && !aboard) {
            return BOARD_TO_SAIL;
        }
        return NONE;
    }
}

package com.harbourmaster.model;

import com.harbourmaster.tracker.CargoTracker;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public final class HarbourmasterSnapshot {
    public final boolean loggedIn;
    public final RoutePlan route;
    public final boolean boardOpen;
    public final int freeSlots;
    public final DockChecklist dock;
    public final Map<Integer, CargoTracker.Destination> cargo;
    public final boolean depositCargo;
    public final CourierPlan courierPlan;
    public final List<NavigationPath> navigation;
    public final RouteLeg currentLeg;

    public HarbourmasterSnapshot(
            boolean loggedIn,
            RoutePlan route,
            boolean boardOpen,
            int freeSlots,
            DockChecklist dock,
            Map<Integer, CargoTracker.Destination> cargo,
            boolean depositCargo) {
        this(loggedIn, route, boardOpen, freeSlots, dock, cargo, depositCargo, null);
    }

    public HarbourmasterSnapshot(
            boolean loggedIn,
            RoutePlan route,
            boolean boardOpen,
            int freeSlots,
            DockChecklist dock,
            Map<Integer, CargoTracker.Destination> cargo,
            boolean depositCargo,
            CourierPlan courierPlan) {
        this.loggedIn = loggedIn;
        this.route = route;
        this.boardOpen = boardOpen;
        this.freeSlots = freeSlots;
        this.cargo = Map.copyOf(cargo);
        this.depositCargo = depositCargo;
        this.courierPlan = courierPlan;
        RouteLeg approach = !route.stops.isEmpty() && route.stops.get(0).arrival != null
                ? route.stops.get(0).arrival
                : route.legs.stream().findFirst().orElse(null);
        currentLeg = approach != null
                        && !approach.steps.isEmpty()
                        && approach.to == nextPort()
                        && (dock.port != nextPort() || !approach.sailingOnly())
                ? approach
                : null;
        this.dock = currentLeg == null ? dock.follow(route) : dock.withoutActions();
        navigation = List.copyOf(route.legs.stream()
                .flatMap(leg -> leg.steps.stream()
                        .filter(step -> step.kind == TravelStep.Kind.SAIL)
                        .map(step -> new NavigationPath(leg, step.points)))
                .collect(Collectors.toList()));
    }

    public boolean sailingNext() {
        return currentLeg != null
                && !currentLeg.steps.isEmpty()
                && currentLeg.steps.get(0).kind == TravelStep.Kind.SAIL;
    }

    public static HarbourmasterSnapshot empty() {
        return new HarbourmasterSnapshot(
                false, RoutePlan.empty(), false, 0, DockChecklist.at(null, List.of()), Map.of(), false);
    }

    public Port nextPort() {
        return route.stops.isEmpty() ? null : route.stops.get(0).port;
    }

    public boolean recommends(CourierTask task) {
        return freeSlots > 0
                && route.nextActions().stream()
                        .anyMatch(event -> event.action == RouteEvent.Action.ACCEPT && event.task.id == task.id);
    }
}

package com.harbourmaster.model;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

public final class NavigationPath {
    public final RouteLeg leg;
    public final List<Sample> points;

    public NavigationPath(RouteLeg leg) {
        this(leg, leg.points);
    }

    public NavigationPath(RouteLeg leg, List<WorldPoint> points) {
        this.leg = leg;
        List<Sample> sampled = new ArrayList<>();
        for (int index = 1; index < points.size(); index++) {
            WorldPoint from = points.get(index - 1);
            WorldPoint to = points.get(index);
            int count = Math.max(1, (int) Math.ceil(Math.hypot(to.getX() - from.getX(), to.getY() - from.getY()) / 4));
            for (int step = 0; step < count; step++) {
                double fraction = (double) step / count;
                sampled.add(new Sample(
                        from.getX() + (to.getX() - from.getX()) * fraction,
                        from.getY() + (to.getY() - from.getY()) * fraction,
                        from.getPlane()));
            }
        }
        if (!points.isEmpty()) {
            WorldPoint last = points.get(points.size() - 1);
            sampled.add(new Sample(last.getX(), last.getY(), last.getPlane()));
        }
        this.points = List.copyOf(sampled);
    }

    public static final class Sample {
        public final WorldPoint tile;
        public final double offsetX;
        public final double offsetY;

        public Sample(double x, double y, int plane) {
            tile = new WorldPoint((int) Math.floor(x), (int) Math.floor(y), plane);
            offsetX = x - tile.getX();
            offsetY = y - tile.getY();
        }
    }
}

