public final class RouteLeg {
    public final Port from;

    public final Port to;
    public final double distance;
    public final List<WorldPoint> points;
    public final List<TravelStep> steps;
    private final double travelTicks;

    public RouteLeg(Port from, Port to, double distance, List<WorldPoint> points) {
        this(
                from,
                to,
                distance,
                points,
                List.of(new TravelStep(
                        TravelStep.Kind.SAIL,
                        to == null ? "Sail" : "Sail to " + to.name,
                        distance / 4 + (from == to ? 0 : 2),
                        points)));
    }

    public RouteLeg(Port from, Port to, double distance, List<WorldPoint> points, List<TravelStep> steps) {
        this.from = from;
        this.to = to;
        this.distance = distance;
        this.points = List.copyOf(points);
        this.steps = List.copyOf(steps);
        double ticks = 0;
        for (TravelStep step : steps) {
            ticks += step.ticks;
        }
        travelTicks = ticks;
    }

    public double travelTicks() {
        return travelTicks;
    }

    public boolean sailingOnly() {
        return steps.stream().allMatch(step -> step.kind == TravelStep.Kind.SAIL);
    }
}

package com.harbourmaster.model;

import java.util.List;
import java.util.stream.Collectors;

public final class RoutePlan {
    public final boolean available;
    public final String reason;
    public final double distance;
    public final List<RouteLeg> legs;
    public final List<RouteStop> stops;

    public RoutePlan(boolean available, String reason, double distance, List<RouteLeg> legs, List<RouteStop> stops) {
        this.available = available;
        this.reason = reason;
        this.distance = distance;
        this.legs = List.copyOf(legs);
        this.stops = List.copyOf(stops);
    }

    public static RoutePlan unavailable(String reason) {
        return new RoutePlan(false, reason, 0, List.of(), List.of());
    }

    public static RoutePlan empty() {
        return new RoutePlan(true, "", 0, List.of(), List.of());
    }

    public List<RouteEvent> nextActions() {
        if (stops.isEmpty()) {
            return List.of();
        }
        List<RouteEvent> events = stops.get(0).events;
        boolean accepting = events.get(0).action == RouteEvent.Action.ACCEPT;
        return events.stream()
                .takeWhile(event -> (event.action == RouteEvent.Action.ACCEPT) == accepting)
                .collect(Collectors.toList());
    }
}

