package com.harbourmaster.optimizer;

import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierPlan;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RoutePlan;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

public final class CourierCyclePlanner {
    private static final int BUNDLE_SEARCH_WIDTH = 8;
    private static final int MAX_ROUTE_EVENTS = 15;
    private final RouteOptimizer optimizer;
    private final CourierTimeModel timeModel = new CourierTimeModel();

    public CourierCyclePlanner(RouteOptimizer optimizer) {
        this.optimizer = optimizer;
    }

    public CourierPlan plan(
            Port start,
            WorldPoint boatPosition,
            List<ActiveTask> held,
            Map<Port, List<CourierTask>> observedOffers,
            int sailingLevel,
            int freeSlots,
            int tasksUntilReset) {
        return plan(start, boatPosition, held, observedOffers, sailingLevel, freeSlots, tasksUntilReset, List.of());
    }

    public CourierPlan plan(
            Port start,
            WorldPoint boatPosition,
            List<ActiveTask> held,
            Map<Port, List<CourierTask>> observedOffers,
            int sailingLevel,
            int freeSlots,
            int tasksUntilReset,
            List<CourierTask> retainedOffers) {
        CourierPlan best = evaluate(start, boatPosition, held, List.of(), freeSlots, tasksUntilReset);
        if (!best.available) {
            return best;
        }
        int incompleteTasks = 0;
        int heldEvents = 0;
        for (ActiveTask task : held) {
            if (task.isFinished()) {
                continue;
            }
            incompleteTasks++;
            heldEvents += (task.pickupRemaining() > 0 ? 1 : 0) + 1;
        }
        int maximumOffers = (MAX_ROUTE_EVENTS - heldEvents) / 3;
        if (freeSlots + incompleteTasks == 0) {
            return best;
        }
        List<CourierTask> candidates = candidates(held, observedOffers, sailingLevel);
        List<CourierTask> remaining =
                retainedOffers.stream().filter(candidates::contains).collect(Collectors.toList());
        if (!remaining.isEmpty()) {
            CourierPlan continued = evaluate(start, boatPosition, held, remaining, freeSlots, tasksUntilReset);
            if (continued.available) {
                return continued;
            }
        }
        List<CourierPlan> frontier = new ArrayList<>();
        for (CourierTask task : candidates) {
            CourierPlan plan = evaluate(start, boatPosition, held, List.of(task), freeSlots, tasksUntilReset);
            if (!plan.available) {
                continue;
            }
            frontier.add(plan);
            if (better(plan, best)) {
                best = plan;
            }
        }
        Comparator<CourierPlan> ranking = Comparator.comparingDouble((CourierPlan plan) -> plan.experiencePerHour)
                .reversed()
                .thenComparing(Comparator.comparingInt((CourierPlan plan) -> plan.courierExperience)
                        .reversed());
        for (int size = 2; size <= maximumOffers; size++) {
            List<CourierPlan> expanded = new ArrayList<>();
            Set<Set<CourierTask>> visited = new HashSet<>();
            for (CourierPlan partial : frontier) {
                for (CourierTask task : candidates) {
                    if (partial.selectedOffers.contains(task)) {
                        continue;
                    }
                    List<CourierTask> offers = new ArrayList<>(partial.selectedOffers);
                    offers.add(task);
                    if (!visited.add(Set.copyOf(offers))) {
                        continue;
                    }
                    CourierPlan plan = evaluate(start, boatPosition, held, offers, freeSlots, tasksUntilReset);
                    if (!plan.available) {
                        continue;
                    }
                    expanded.add(plan);
                    if (better(plan, best)) {
                        best = plan;
                    }
                }
            }
            expanded.sort(ranking);
            frontier = expanded.subList(0, Math.min(BUNDLE_SEARCH_WIDTH, expanded.size()));
        }
        return best;
    }

    public CourierPlan relocate(CourierPlan plan, Port start, WorldPoint boatPosition) {
        return withRoute(plan, optimizer.relocate(plan.route, start, boatPosition));
    }

    public CourierPlan withRoute(CourierPlan plan, RoutePlan route) {
        return new CourierPlan(
                route,
                plan.selectedOffers,
                plan.courierExperience,
                timeModel.experiencePerHour(route, plan.courierExperience));
    }

    private CourierPlan evaluate(
            Port start,
            WorldPoint boatPosition,
            List<ActiveTask> held,
            List<CourierTask> offers,
            int freeSlots,
            int tasksUntilReset) {
        RoutePlan route = optimizer.optimizeWithOffers(start, boatPosition, held, offers, freeSlots, tasksUntilReset);
        if (!route.available) {
            return new CourierPlan(route, offers, 0, 0);
        }
        int experience = held.stream()
                        .filter(task -> !task.isFinished())
                        .mapToInt(task -> Math.max(0, task.definition.experience))
                        .sum()
                + offers.stream().mapToInt(task -> task.experience).sum();
        return new CourierPlan(route, offers, experience, timeModel.experiencePerHour(route, experience));
    }

    private static List<CourierTask> candidates(
            List<ActiveTask> held, Map<Port, List<CourierTask>> observedOffers, int sailingLevel) {
        Set<Integer> excludedIds = new HashSet<>();
        for (ActiveTask task : held) {
            excludedIds.add(task.taskId);
        }
        List<CourierTask> candidates = new ArrayList<>();
        for (List<CourierTask> offers : observedOffers.values()) {
            for (CourierTask task : offers) {
                if (task.delivery.noticeboardObject < 0
                        || task.experience < 0
                        || task.level > sailingLevel
                        || !excludedIds.add(task.id)) {
                    continue;
                }
                candidates.add(task);
            }
        }
        candidates.sort(Comparator.comparingInt((CourierTask task) -> task.board.ordinal())
                .thenComparingInt(task -> task.id));
        return candidates;
    }

    private static boolean better(CourierPlan candidate, CourierPlan current) {
        if (!candidate.available) {
            return false;
        }
        return candidate.experiencePerHour > current.experiencePerHour
                || (candidate.experiencePerHour == current.experiencePerHour
                        && candidate.courierExperience > current.courierExperience);
    }
}

package com.harbourmaster.optimizer;

import com.harbourmaster.model.RouteLeg;
import com.harbourmaster.model.RoutePlan;
import com.harbourmaster.model.RouteStop;

final class CourierTimeModel {
    private static final double TICKS_PER_HOUR = 6000;

    public double experiencePerHour(RoutePlan route, int experience) {
        if (!route.available) {
            return 0;
        }

        double ticks =
                route.legs.stream().mapToDouble(CourierTimeModel::travelTicks).sum();
        for (RouteStop stop : route.stops) {
            ticks += stop.events.size();
        }
        return ticks <= 0 ? 0 : experience * TICKS_PER_HOUR / ticks;
    }

    static double travelTicks(RouteLeg leg) {
        return leg.travelTicks();
    }
}

package com.harbourmaster.optimizer;

import com.harbourmaster.data.PortGraph;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RouteLeg;
import com.harbourmaster.model.RoutePlan;
import com.harbourmaster.model.RouteStop;
import com.harbourmaster.model.TravelContext;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CancellationException;
import net.runelite.api.coords.WorldPoint;

public final class RouteOptimizer {
    private static final double EPSILON = 0.0000001;
    private final PortGraph graph;
    private final TravelRoutePlanner travelPlanner;

    public RouteOptimizer(PortGraph graph) {
        this(graph, null);
    }

    public RouteOptimizer(PortGraph graph, TravelContext travel) {
        this.graph = graph;
        travelPlanner = travel == null ? null : new TravelRoutePlanner(graph, travel);
    }

    public RoutePlan optimize(Port start, List<ActiveTask> tasks) {
        return optimize(start, null, tasks, null);
    }

    public RoutePlan optimize(Port start, WorldPoint boatPosition, List<ActiveTask> tasks, Port firstStop) {
        return plan(start, boatPosition, tasks, List.of(), 0, 0, firstStop);
    }

    public RoutePlan optimizeWithOffers(
            Port start,
            WorldPoint boatPosition,
            List<ActiveTask> held,
            List<CourierTask> offers,
            int freeSlots,
            int tasksUntilReset) {
        return plan(start, boatPosition, held, offers, freeSlots, tasksUntilReset, null);
    }

    private RoutePlan plan(
            Port start,
            WorldPoint boatPosition,
            List<ActiveTask> held,
            List<CourierTask> offers,
            int freeSlots,
            int tasksUntilReset,
            Port firstStop) {
        List<RouteEvent> events = new ArrayList<>();
        List<Integer> taskLengths = new ArrayList<>();
        for (ActiveTask active : held) {
            if (active.definition == null) {
                return RoutePlan.unavailable("Unrecognized active task " + active.taskId);
            }
            if (active.isFinished()) {
                continue;
            }
            CourierTask task = active.definition;
            if (active.pickupRemaining() > 0) {
                events.add(new RouteEvent(
                        active.slot, task, RouteEvent.Action.PICKUP, task.pickup, active.pickupRemaining()));
            }
            events.add(new RouteEvent(
                    active.slot, task, RouteEvent.Action.DELIVER, task.delivery, active.deliveryRemaining()));
            taskLengths.add(active.pickupRemaining() > 0 ? 2 : 1);
        }
        for (CourierTask task : offers) {
            events.add(new RouteEvent(-1, task, RouteEvent.Action.ACCEPT, task.board, 0));
            events.add(new RouteEvent(-1, task, RouteEvent.Action.PICKUP, task.pickup, task.quantity));
            events.add(new RouteEvent(-1, task, RouteEvent.Action.DELIVER, task.delivery, task.quantity));
            taskLengths.add(3);
        }
        if (travelPlanner != null) {
            return travelPlanner.plan(
                    start, boatPosition, held, events, taskLengths, firstStop, freeSlots, tasksUntilReset);
        }
        return optimize(start, boatPosition, events, taskLengths, firstStop, freeSlots, tasksUntilReset);
    }

    private RoutePlan optimize(
            Port start,
            WorldPoint boatPosition,
            List<RouteEvent> events,
            List<Integer> taskLengths,
            Port firstStop,
            int freeSlots,
            int tasksUntilReset) {
        if (Thread.currentThread().isInterrupted()) {
            throw new CancellationException("Courier plan cancelled");
        }
        if (events.isEmpty()) {
            return RoutePlan.empty();
        }
        if (start == null && boatPosition == null) {
            return RoutePlan.unavailable("Visit a known port to establish the route start");
        }
        int count = events.size();
        int[] increments = new int[count];
        int[] offsets = new int[taskLengths.size()];
        int stateCount = 1;
        int offset = 0;
        for (int task = 0; task < taskLengths.size(); task++) {
            offsets[task] = offset;
            int length = taskLengths.get(task);
            Arrays.fill(increments, offset, offset + length, stateCount);
            stateCount *= length + 1;
            offset += length;
        }
        RouteLeg[][] journeys = new RouteLeg[count + 1][count];
        for (int destination = 0; destination < count; destination++) {
            journeys[count][destination] = journey(start, boatPosition, events.get(destination).port);
            for (int origin = 0; origin < count; origin++) {
                journeys[origin][destination] = graph.route(events.get(origin).port, events.get(destination).port)
                        .orElse(null);
            }
        }
        int positions = count + 1;
        double[] times = new double[stateCount * positions];
        int[] parents = new int[times.length];
        Arrays.fill(times, Double.POSITIVE_INFINITY);
        Arrays.fill(parents, -1);
        times[count] = 0;
        for (int state = 0; state < stateCount; state++) {
            if (Thread.currentThread().isInterrupted()) {
                throw new CancellationException("Courier plan cancelled");
            }
            int completedTasks = 0;
            int availableSlots = freeSlots;
            for (int task = 0; task < taskLengths.size(); task++) {
                int progress = state / increments[offsets[task]] % (taskLengths.get(task) + 1);
                if (progress == taskLengths.get(task)) {
                    completedTasks++;
                    availableSlots++;
                }
                if (progress > 0 && events.get(offsets[task]).action == RouteEvent.Action.ACCEPT) {
                    availableSlots--;
                }
            }
            for (int task = 0; task < taskLengths.size(); task++) {
                int progress = state / increments[offsets[task]] % (taskLengths.get(task) + 1);
                if (progress == taskLengths.get(task)) {
                    continue;
                }
                int next = offsets[task] + progress;
                RouteEvent event = events.get(next);
                if (event.action == RouteEvent.Action.ACCEPT
                        && (availableSlots == 0 || completedTasks >= tasksUntilReset)) {
                    continue;
                }
                if (state == 0 && firstStop != null && event.port != firstStop) {
                    continue;
                }
                int combined = (state + increments[next]) * positions + next;
                for (int previous = 0; previous < positions; previous++) {
                    double elapsed = times[state * positions + previous];
                    RouteLeg journey = journeys[previous][next];
                    if (!Double.isFinite(elapsed) || journey == null) {
                        continue;
                    }
                    double time = elapsed + CourierTimeModel.travelTicks(journey);
                    if (time < times[combined] - EPSILON) {
                        times[combined] = time;
                        parents[combined] = previous;
                    }
                }
            }
        }
        int complete = stateCount - 1;
        int last = -1;
        for (int event = 0; event < count; event++) {
            if (Double.isFinite(times[complete * positions + event])
                    && (last < 0
                            || times[complete * positions + event] < times[complete * positions + last] - EPSILON)) {
                last = event;
            }
        }
        if (last < 0) {
            return RoutePlan.unavailable("Route unavailable: unknown or disconnected port");
        }

        List<RouteEvent> ordered = new ArrayList<>();
        for (int state = complete; state > 0; ) {
            ordered.add(events.get(last));
            int parent = parents[state * positions + last];
            state -= increments[last];
            last = parent;
        }
        Collections.reverse(ordered);
        List<RouteLeg> legs = new ArrayList<>();
        List<RouteStop> stops = new ArrayList<>();
        Port position = start;
        if (boatPosition != null) {
            legs.add(journey(start, boatPosition, ordered.get(0).port));
            position = ordered.get(0).port;
        }
        for (RouteEvent event : ordered) {
            if (position != event.port) {
                legs.add(graph.route(position, event.port).orElseThrow(IllegalStateException::new));
                position = event.port;
            }
            if (stops.isEmpty() || stops.get(stops.size() - 1).port != event.port) {
                stops.add(new RouteStop(event.port, List.of(event)));
            } else {
                List<RouteEvent> grouped = new ArrayList<>(stops.remove(stops.size() - 1).events);
                int positionInStop = grouped.size();
                if (event.action == RouteEvent.Action.ACCEPT) {
                    while (positionInStop > 0 && grouped.get(positionInStop - 1).action == RouteEvent.Action.PICKUP) {
                        positionInStop--;
                    }
                }
                grouped.add(positionInStop, event);
                stops.add(new RouteStop(event.port, grouped));
            }
        }
        return new RoutePlan(
                true, "", legs.stream().mapToDouble(leg -> leg.distance).sum(), legs, stops);
    }

    public RoutePlan relocate(RoutePlan plan, Port start, WorldPoint boatPosition) {
        if (plan.stops.isEmpty()) {
            return RoutePlan.empty();
        }
        Port destination = plan.stops.get(0).port;
        RouteLeg approach = journey(start, boatPosition, destination);
        if (approach == null) {
            return RoutePlan.unavailable("Route unavailable: unknown or disconnected port");
        }
        List<RouteLeg> legs = new ArrayList<>(plan.legs);
        double distance = plan.distance;
        if (!legs.isEmpty() && legs.get(0).to == destination) {
            distance -= legs.remove(0).distance;
        }
        if (boatPosition != null || start != destination) {
            legs.add(0, approach);
            distance += approach.distance;
        }
        List<RouteStop> stops = new ArrayList<>(plan.stops);
        if (stops.get(0).arrival != null) {
            stops.set(0, new RouteStop(destination, stops.get(0).events, approach));
        }
        return new RoutePlan(true, "", distance, legs, stops);
    }

    private RouteLeg journey(Port start, WorldPoint boatPosition, Port destination) {
        return (boatPosition == null
                        ? graph.route(start, destination)
                        : graph.routeFromPosition(boatPosition, destination))
                .orElse(null);
    }
}

package com.harbourmaster.optimizer;

import com.harbourmaster.data.PortGraph;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RouteLeg;
import com.harbourmaster.model.RoutePlan;
import com.harbourmaster.model.RouteStop;
import com.harbourmaster.model.TravelContext;
import com.harbourmaster.model.TravelMethod;
import com.harbourmaster.model.TravelStep;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CancellationException;
import net.runelite.api.coords.WorldPoint;

final class TravelRoutePlanner {
    private final PortGraph graph;
    private final TravelContext travel;
    private final Map<List<Port>, List<Journey>> playerRoutes = new HashMap<>();
    private final Map<List<Object>, List<Journey>> cachedJourneys = new HashMap<>();

    TravelRoutePlanner(PortGraph graph, TravelContext travel) {
        this.graph = graph;
        this.travel = travel;
    }

    RoutePlan plan(
            Port start,
            WorldPoint boatPosition,
            List<ActiveTask> held,
            List<RouteEvent> events,
            List<Integer> taskLengths,
            Port firstStop,
            int freeSlots,
            int tasksUntilReset) {
        if (travel.boat == 0 || boatPosition == null && (start == null || travel.boatPort == null)) {
            return RoutePlan.unavailable("Board your courier boat to establish its location");
        }
        if (events.isEmpty()) {
            return RoutePlan.empty();
        }
        held = held.stream().filter(task -> !task.isFinished()).collect(java.util.stream.Collectors.toList());
        int[] offsets = new int[taskLengths.size()];
        int[] increments = new int[taskLengths.size()];
        int stateCount = 1;
        int offset = 0;
        for (int task = 0; task < taskLengths.size(); task++) {
            offsets[task] = offset;
            increments[task] = stateCount;
            offset += taskLengths.get(task);
            stateCount *= taskLengths.get(task) + 1;
        }
        Map<Integer, List<Visit>> states = new HashMap<>();
        states.put(0, new ArrayList<>(List.of(new Visit(start, travel.boatPort, 0, null, null, null))));
        for (int state = 0; state < stateCount - 1; state++) {
            if (Thread.currentThread().isInterrupted()) {
                throw new CancellationException("Courier plan cancelled");
            }
            List<Visit> visits = states.remove(state);
            if (visits == null) {
                continue;
            }
            int slots = freeSlots;
            int completed = 0;
            boolean loaded = false;
            int heldIndex = 0;
            for (int task = 0; task < taskLengths.size(); task++) {
                int progress = state / increments[task] % (taskLengths.get(task) + 1);
                boolean offer = events.get(offsets[task]).action == RouteEvent.Action.ACCEPT;
                if (progress == taskLengths.get(task)) {
                    slots++;
                    completed++;
                } else if (offer) {
                    loaded |= progress == 2;
                } else {
                    loaded |= progress > 0 || held.get(heldIndex).carried() > 0;
                }
                if (!offer) {
                    heldIndex++;
                }
                if (offer && progress > 0) {
                    slots--;
                }
            }
            for (int task = 0; task < taskLengths.size(); task++) {
                int progress = state / increments[task] % (taskLengths.get(task) + 1);
                if (progress == taskLengths.get(task)) {
                    continue;
                }
                RouteEvent event = events.get(offsets[task] + progress);
                if (event.action == RouteEvent.Action.ACCEPT && (slots == 0 || completed >= tasksUntilReset)
                        || state == 0 && firstStop != null && event.port != firstStop) {
                    continue;
                }
                List<Visit> next = states.computeIfAbsent(state + increments[task], ignored -> new ArrayList<>());
                for (Visit visit : visits) {
                    for (Journey journey : journeys(visit, event, loaded, state == 0, boatPosition)) {
                        add(
                                next,
                                new Visit(
                                        event.port,
                                        journey.boat,
                                        visit.ticks + journey.leg.travelTicks(),
                                        visit,
                                        event,
                                        journey.leg));
                    }
                }
            }
        }
        Visit best = states.getOrDefault(stateCount - 1, List.of()).stream()
                .min(java.util.Comparator.comparingDouble(visit -> visit.ticks))
                .orElse(null);
        if (best == null) {
            return RoutePlan.unavailable("No complete route with your enabled travel methods");
        }
        List<Visit> ordered = new ArrayList<>();
        for (Visit visit = best; visit.previous != null; visit = visit.previous) {
            ordered.add(visit);
        }
        Collections.reverse(ordered);
        List<RouteLeg> legs = new ArrayList<>();
        List<RouteStop> stops = new ArrayList<>();
        for (Visit visit : ordered) {
            if (!visit.leg.steps.isEmpty()) {
                legs.add(visit.leg);
            }
            if (stops.isEmpty() || stops.get(stops.size() - 1).port != visit.player || !visit.leg.steps.isEmpty()) {
                stops.add(new RouteStop(visit.player, List.of(visit.event), visit.leg));
                continue;
            }
            RouteStop previous = stops.remove(stops.size() - 1);
            List<RouteEvent> grouped = new ArrayList<>(previous.events);
            int positionInStop = grouped.size();
            if (visit.event.action == RouteEvent.Action.ACCEPT) {
                while (positionInStop > 0 && grouped.get(positionInStop - 1).action == RouteEvent.Action.PICKUP) {
                    positionInStop--;
                }
            }
            grouped.add(positionInStop, visit.event);
            stops.add(new RouteStop(visit.player, grouped, previous.arrival));
        }
        return new RoutePlan(
                true, "", legs.stream().mapToDouble(leg -> leg.distance).sum(), legs, stops);
    }

    private List<Journey> journeys(
            Visit visit, RouteEvent event, boolean loaded, boolean initial, WorldPoint boatPosition) {
        return cachedJourneys.computeIfAbsent(
                Arrays.asList(
                        visit.player,
                        visit.boat,
                        event.port,
                        event.action == RouteEvent.Action.ACCEPT,
                        loaded,
                        initial,
                        boatPosition),
                ignored -> findJourneys(visit, event, loaded, initial, boatPosition));
    }

    private List<Journey> findJourneys(
            Visit visit, RouteEvent event, boolean loaded, boolean initial, WorldPoint boatPosition) {
        List<Journey> result = new ArrayList<>();
        boolean canLeave = !travel.carryingCargo && visit.boat != null;
        if (event.action == RouteEvent.Action.ACCEPT) {
            if (visit.player == event.port && visit.boat != null) {
                result.add(new Journey(visit.boat, empty(visit.player)));
            } else if (canLeave) {
                result.addAll(playerJourneys(visit.player, event.port, visit.boat));
            }
        }
        // A cargo action always takes place with the courier boat at this port.
        if (visit.boat == event.port && visit.player == event.port) {
            result.add(new Journey(visit.boat, empty(visit.player)));
            return result;
        }
        List<Journey> returns = new ArrayList<>();
        if (visit.player == visit.boat || visit.boat == null && initial && travel.aboard) {
            returns.add(new Journey(visit.boat, empty(visit.player)));
        } else if (canLeave) {
            returns.addAll(playerJourneys(visit.player, visit.boat, visit.boat));
        }
        RouteLeg sailing = (visit.boat == null
                        ? graph.routeFromPosition(boatPosition, event.port)
                        : graph.route(visit.boat, event.port))
                .orElse(null);
        if (sailing != null) {
            for (Journey back : returns) {
                result.add(new Journey(event.port, join(visit.player, event.port, back.leg, sailing)));
            }
        }
        if (!loaded && travel.summonSafe && canLeave && visit.boat != event.port) {
            for (Journey outward : playerJourneys(visit.player, event.port, visit.boat)) {
                for (TravelMethod summon : travel.summons) {
                    result.add(new Journey(
                            event.port,
                            join(visit.player, event.port, outward.leg, summon.leg(event.port, event.port))));
                }
            }
        }
        return result;
    }

    private List<Journey> playerJourneys(Port from, Port to, Port boat) {
        return playerRoutes.computeIfAbsent(List.of(from, to, boat), ignored -> findPlayerJourneys(from, to, boat));
    }

    private List<Journey> findPlayerJourneys(Port from, Port to, Port boat) {
        if (from == to) {
            return List.of(new Journey(boat, empty(from)));
        }
        List<Journey> result = new ArrayList<>();
        for (TravelMethod method : travel.methods) {
            Port destination = method.boat == travel.boat && method.boat != 0 ? boat : method.destination;
            if (destination == null || method.origin != null && method.origin != from) {
                continue;
            }
            RouteLeg first = method.leg(from, destination);
            if (destination == to) {
                result.add(new Journey(boat, first));
                continue;
            }
            if (method.kind != TravelStep.Kind.TELEPORT) {
                continue;
            }
            // The wiki routes also use an amulet teleport to reach a charter crew.
            for (TravelMethod charter : travel.methods) {
                if (charter.kind != TravelStep.Kind.CHARTER
                        || charter.origin != destination
                        || charter.destination != to) {
                    continue;
                }
                result.add(new Journey(boat, join(from, to, first, charter.leg(destination, to))));
            }
        }
        return result.stream()
                .min(java.util.Comparator.comparingDouble(journey -> journey.leg.travelTicks()))
                .map(List::of)
                .orElse(List.of());
    }

    private static void add(List<Visit> visits, Visit candidate) {
        for (Visit visit : visits) {
            if (visit.player == candidate.player && visit.boat == candidate.boat && visit.ticks <= candidate.ticks) {
                return;
            }
        }
        visits.removeIf(visit -> visit.player == candidate.player && visit.boat == candidate.boat);
        visits.add(candidate);
    }

    private static RouteLeg empty(Port port) {
        return new RouteLeg(port, port, 0, List.of(), List.of());
    }

    private static RouteLeg join(Port from, Port to, RouteLeg first, RouteLeg second) {
        if (first.steps.isEmpty() && second.from == from && second.to == to) {
            return second;
        }
        List<TravelStep> steps = new ArrayList<>(first.steps);
        if (second.from != second.to || second.distance > 0 || !second.sailingOnly()) {
            steps.addAll(second.steps);
        }
        return new RouteLeg(from, to, first.distance + second.distance, List.of(), steps);
    }

    private static final class Journey {
        final Port boat;
        final RouteLeg leg;

        Journey(Port boat, RouteLeg leg) {
            this.boat = boat;
            this.leg = leg;
        }
    }

    private static final class Visit {
        final Port player;
        final Port boat;
        final double ticks;
        final Visit previous;
        final RouteEvent event;
        final RouteLeg leg;

        Visit(Port player, Port boat, double ticks, Visit previous, RouteEvent event, RouteLeg leg) {
            this.player = player;
            this.boat = boat;
            this.ticks = ticks;
            this.previous = previous;
            this.event = event;
            this.leg = leg;
        }
    }
}

package com.harbourmaster.overlay;

import com.harbourmaster.HarbourmasterConfig;
import com.harbourmaster.HarbourmasterPlugin;
import com.harbourmaster.model.HarbourmasterSnapshot;
import com.harbourmaster.tracker.CargoTracker;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

public final class CargoOverlay extends WidgetItemOverlay {
    private final HarbourmasterPlugin plugin;
    private final HarbourmasterConfig config;
    private final ItemManager items;
    private final TooltipManager tooltips;
    private final Client client;

    @Inject
    public CargoOverlay(
            HarbourmasterPlugin plugin,
            HarbourmasterConfig config,
            ItemManager items,
            TooltipManager tooltips,
            Client client) {
        this.plugin = plugin;
        this.config = config;
        this.items = items;
        this.tooltips = tooltips;
        this.client = client;
        showOnInventory();
        showOnInterfaces(InterfaceID.SAILING_BOAT_CARGOHOLD, InterfaceID.SAILING_BOAT_CARGOHOLD_SIDE);
    }

    @Override
    public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem item) {
        if (!plugin.isGuidanceActive()) {
            return;
        }
        HarbourmasterSnapshot state = plugin.getSnapshot();
        CargoTracker.Destination destination = state.cargo.get(itemId);
        if (destination == null) {
            return;
        }
        Rectangle bounds = item.getCanvasBounds();
        boolean unload = (state.dock.unloads(itemId) || destination.unload && plugin.shouldUnloadCargo())
                && config.highlightUnloadCrates();
        if (unload) {
            graphics.drawImage(
                    items.getItemOutline(itemId, item.getQuantity(), config.unloadColor()), bounds.x, bounds.y, null);
        }
        if (config.showCargoDestinations() || unload) {
            Graphics2D drawing = (Graphics2D) graphics.create();
            drawing.setFont(FontManager.getRunescapeSmallFont());
            String text = unload ? "Unload" : destination.port.name;
            while (text.length() > 1 && drawing.getFontMetrics().stringWidth(text) > bounds.width) {
                text = text.substring(0, text.length() - 1);
            }
            drawing.setColor(Color.BLACK);
            drawing.drawString(text, bounds.x + 1, bounds.y + bounds.height);
            drawing.setColor(unload ? config.unloadColor() : Color.WHITE);
            drawing.drawString(text, bounds.x, bounds.y + bounds.height - 1);
            drawing.dispose();
            Point mouse = client.getMouseCanvasPosition();
            if (bounds.contains(mouse.getX(), mouse.getY())) {
                tooltips.add(new Tooltip((unload ? "Unload here: " : "Deliver to: ") + destination.port.name));
            }
        }
    }
}

package com.harbourmaster.overlay;

import com.harbourmaster.HarbourmasterConfig;
import com.harbourmaster.HarbourmasterPlugin;
import com.harbourmaster.data.CargoHoldObjects;
import com.harbourmaster.model.DockGuidance;
import com.harbourmaster.model.HarbourmasterSnapshot;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteEvent;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

public final class DockOverlay extends Overlay {
    private final Client client;
    private final HarbourmasterPlugin plugin;
    private final HarbourmasterConfig config;

    @Inject
    public DockOverlay(Client client, HarbourmasterPlugin plugin, HarbourmasterConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.isGuidanceActive() || client.getLocalPlayer() == null) {
            return null;
        }
        HarbourmasterSnapshot state = plugin.getSnapshot();
        DockGuidance guidance = plugin.getDockGuidance();
        Color color = guidance.unload ? config.unloadColor() : config.loadColor();
        WorldView playerWorld = client.getLocalPlayer().getWorldView();
        for (TileObject object : plugin.getPorts().getObjects()) {
            Port port = Port.fromObject(object.getId());
            if (config.highlightGangplank()
                    && state.dock.port != null
                    && guidance.target == DockGuidance.Target.GANGPLANK) {
                boolean shoreGangplank = port == state.dock.port
                        && object.getId() == port.gangplankObject
                        && object.getWorldView().isTopLevel();
                boolean ownGangplank = object.getId() == ObjectID.SAILING_GANGPLANK_PROXY
                        && !playerWorld.isTopLevel()
                        && object.getWorldView() == playerWorld;
                if (shoreGangplank) {
                    draw(graphics, object, color, List.of(guidance.instruction));
                }
                if (ownGangplank) {
                    drawGangplank(graphics, (GameObject) object, color, List.of(guidance.instruction));
                }
            }
            if (port != null && object.getId() == port.noticeboardObject && config.highlightNoticeboards()) {
                if (guidance.target == DockGuidance.Target.NOTICEBOARD && port == state.dock.port
                        || state.freeSlots == 0 && config.subdueFullBoards()) {
                    drawNoticeboard(graphics, object, port, state);
                }
            }
            if (guidance.target == DockGuidance.Target.LEDGER
                    && port == state.dock.port
                    && object.getId() == port.ledgerObject
                    && config.highlightLedger()) {
                List<String> lines = new ArrayList<>();
                lines.add(port.name + " ledger");
                for (RouteEvent action : state.dock.actions) {
                    if ((action.action == RouteEvent.Action.DELIVER) == guidance.unload) {
                        lines.add(action.description());
                    }
                }
                draw(graphics, object, color, lines);
            }
            if (config.highlightCargoHold()
                    && guidance.target == DockGuidance.Target.CARGO_HOLD
                    && CargoHoldObjects.IDS.contains(object.getId())
                    && !object.getWorldView().isTopLevel()
                    && object.getWorldView() == playerWorld) {
                draw(graphics, object, color, List.of(guidance.instruction));
            }
        }
        return null;
    }

    private void drawNoticeboard(Graphics2D graphics, TileObject object, Port port, HarbourmasterSnapshot state) {
        String label = state.freeSlots + (state.freeSlots == 1 ? " task slot free" : " task slots free");
        Color color = state.freeSlots > 0 ? config.bestOfferColor() : Color.GRAY;
        if (state.freeSlots > 0 && config.enableOptimizer() && config.rankOffers()) {
            if (!plugin.hasReadNoticeboard(port)) {
                label = "Check the noticeboard";
            } else if (plugin.isCalculatingPlan()) {
                label = "Checking offers";
            } else if (state.courierPlan != null && state.courierPlan.available) {
                long recommended = state.route.nextActions().stream()
                        .filter(event -> event.port == port && event.action == RouteEvent.Action.ACCEPT)
                        .count();
                label = recommended > 0
                        ? "Accept " + recommended + (recommended == 1 ? " task" : " tasks")
                        : "No recommended tasks";
                color = recommended > 0 ? config.bestOfferColor() : Color.GRAY;
            }
        }
        draw(graphics, object, color, List.of(label));
    }

    private static void draw(Graphics2D graphics, TileObject object, Color color, List<String> lines) {
        Shape hull = object instanceof GroundObject
                ? ((GroundObject) object).getConvexHull()
                : ((GameObject) object).getConvexHull();
        draw(graphics, object, hull, color, lines);
    }

    private static void drawGangplank(Graphics2D graphics, GameObject proxy, Color color, List<String> lines) {
        WorldView world = proxy.getWorldView();
        if (proxy.getPlane() != world.getPlane()) {
            return;
        }
        LocalPoint location = proxy.getLocalLocation();
        Tile tile = world.getScene().getTiles()[0][location.getSceneX()][location.getSceneY()];
        GroundObject plank = tile == null ? null : tile.getGroundObject();
        if (plank != null) {
            draw(graphics, plank, plank.getConvexHull(), color, lines);
        }
    }

    private static void draw(Graphics2D graphics, TileObject object, Shape hull, Color color, List<String> lines) {
        if (hull != null) {
            OverlayUtil.renderPolygon(
                    graphics,
                    hull,
                    color,
                    new Color(color.getRed(), color.getGreen(), color.getBlue(), 25),
                    new BasicStroke(2));
        }
        int offset = (lines.size() - 1) * 15;
        for (String line : lines) {
            Point point = object.getCanvasTextLocation(graphics, line, 30);
            if (point != null) {
                OverlayUtil.renderTextLocation(graphics, new Point(point.getX(), point.getY() - offset), line, color);
            }
            offset -= 15;
        }
    }
}

package com.harbourmaster.overlay;

import com.harbourmaster.HarbourmasterConfig;
import com.harbourmaster.HarbourmasterPlugin;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.geom.Ellipse2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public final class MinimapRouteOverlay extends Overlay {
    private final Client client;
    private final HarbourmasterPlugin plugin;
    private final HarbourmasterConfig config;

    @Inject
    public MinimapRouteOverlay(Client client, HarbourmasterPlugin plugin, HarbourmasterConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.isGuidanceActive() || !config.showMinimap()) {
            return null;
        }
        Widget minimap = client.getWidget(
                !client.isResized()
                        ? InterfaceID.Toplevel.MINIMAP
                        : client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
                                ? InterfaceID.ToplevelPreEoc.MINIMAP
                                : InterfaceID.ToplevelOsrsStretch.MINIMAP);
        if (minimap == null || minimap.isHidden()) {
            return null;
        }
        Rectangle bounds = minimap.getBounds();
        Graphics2D drawing = (Graphics2D) graphics.create();
        drawing.clip(new Ellipse2D.Double(bounds.x + 5, bounds.y + 5, bounds.width - 10, bounds.height - 10));
        NavigationOverlay.drawPaths(drawing, client, plugin.getSnapshot(), config, true);
        drawing.dispose();
        return null;
    }
}

