import com.harbourmaster.HarbourmasterConfig;
import com.harbourmaster.HarbourmasterPlugin;
import com.harbourmaster.model.HarbourmasterSnapshot;
import com.harbourmaster.model.NavigationPath;
import com.harbourmaster.tracker.PortTracker;
import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public final class NavigationOverlay extends Overlay {
    private final Client client;
    private final HarbourmasterPlugin plugin;
    private final HarbourmasterConfig config;

    @Inject
    public NavigationOverlay(Client client, HarbourmasterPlugin plugin, HarbourmasterConfig config) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.isGuidanceActive() || !config.showWorldRoute()) {
            return null;
        }
        Graphics2D drawing = (Graphics2D) graphics.create();
        drawing.clipRect(
                client.getViewportXOffset(),
                client.getViewportYOffset(),
                client.getViewportWidth(),
                client.getViewportHeight());
        drawPaths(drawing, client, plugin.getSnapshot(), config, false);
        drawing.dispose();
        return null;
    }

    static void drawPaths(
            Graphics2D graphics,
            Client client,
            HarbourmasterSnapshot state,
            HarbourmasterConfig config,
            boolean minimap) {
        WorldPoint position = PortTracker.position(client);
        if (position == null) {
            return;
        }
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        for (int leg = state.navigation.size() - 1; leg >= 0; leg--) {
            NavigationPath path = state.navigation.get(leg);
            boolean current = path.leg == state.currentLeg;
            if (!current && !config.showCompleteRoute()) {
                continue;
            }
            graphics.setColor(current ? config.activeRouteColor() : config.futureRouteColor());
            graphics.setStroke(new BasicStroke(current ? 2.5f : 1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            Point previous = null;
            int segment = 0;
            for (NavigationPath.Sample point : path.points) {
                if (point.tile.distanceTo(position) > (minimap ? 32 : 100)) {
                    previous = null;
                    continue;
                }
                LocalPoint local = localPoint(client, point);
                Point canvas = local == null
                        ? null
                        : minimap
                                ? Perspective.localToMinimap(client, local)
                                : Perspective.localToCanvas(
                                        client,
                                        local,
                                        client.getTopLevelWorldView().getPlane());
                if (canvas != null && previous != null) {
                    drawSegment(graphics, previous, canvas, ++segment % 6 == 0);
                }
                previous = canvas;
            }
        }
    }

    static LocalPoint localPoint(Client client, NavigationPath.Sample sample) {
        LocalPoint tile = localPoint(client, sample.tile);
        if (tile == null) {
            return null;
        }
        double horizontal = sample.offsetX * Perspective.LOCAL_TILE_SIZE;
        double vertical = sample.offsetY * Perspective.LOCAL_TILE_SIZE;
        if (client.getTopLevelWorldView().isInstance()) {
            int template = client.getTopLevelWorldView()
                    .getInstanceTemplateChunks()[client.getTopLevelWorldView().getPlane()][tile.getSceneX() / 8][
                    tile.getSceneY() / 8];
            int rotation = (template >> 1) & 3;
            for (int turn = 0; turn < rotation; turn++) {
                double previousHorizontal = horizontal;
                horizontal = vertical;
                vertical = -previousHorizontal;
            }
        }
        return new LocalPoint(
                tile.getX() + (int) Math.round(horizontal),
                tile.getY() + (int) Math.round(vertical),
                tile.getWorldView());
    }

    static LocalPoint localPoint(Client client, WorldPoint point) {
        for (WorldPoint instance : WorldPoint.toLocalInstance(client.getTopLevelWorldView(), point)) {
            LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), instance);
            if (local != null) {
                return local;
            }
        }
        return null;
    }

    static void drawSegment(Graphics2D graphics, Point from, Point to, boolean arrow) {
        graphics.drawLine(from.getX(), from.getY(), to.getX(), to.getY());
        if (!arrow) {
            return;
        }
        double angle = Math.atan2(to.getY() - from.getY(), to.getX() - from.getX());
        int middleX = (from.getX() + to.getX()) / 2;
        int middleY = (from.getY() + to.getY()) / 2;
        for (double side : new double[] {angle - 0.55, angle + 0.55}) {
            graphics.drawLine(
                    middleX, middleY, middleX - (int) (7 * Math.cos(side)), middleY - (int) (7 * Math.sin(side)));
        }
    }
}

package com.harbourmaster.overlay;

import com.harbourmaster.HarbourmasterConfig;
import com.harbourmaster.HarbourmasterPlugin;
import com.harbourmaster.model.CourierPlan;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.HarbourmasterSnapshot;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

public final class NoticeboardOverlay extends Overlay {
    private final Client client;
    private final HarbourmasterPlugin plugin;
    private final HarbourmasterConfig config;
    private final TooltipManager tooltips;

    @Inject
    public NoticeboardOverlay(
            Client client, HarbourmasterPlugin plugin, HarbourmasterConfig config, TooltipManager tooltips) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.tooltips = tooltips;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        HarbourmasterSnapshot state = plugin.getSnapshot();
        boolean openingDetails = plugin.getNoticeboard().isOpeningDetails();
        boolean boardVisible = visible(InterfaceID.PortTaskBoard.CONTAINER);
        if (visible(InterfaceID.Worldmap.CONTENT)
                || visible(InterfaceID.PortTaskInfo.WINDOW)
                || !openingDetails && !boardVisible) {
            return null;
        }
        if (!config.rankOffers() || !state.boardOpen || plugin.isCalculatingPlan()) {
            return null;
        }
        Graphics2D drawing = (Graphics2D) graphics.create();
        drawing.setColor(config.bestOfferColor());
        drawing.setStroke(new BasicStroke(3));
        Point mouse = client.getMouseCanvasPosition();
        for (CourierTask task : plugin.getNoticeboard().getOffers()) {
            Widget widget = plugin.getNoticeboard().getWidgets().get(task.databaseRow);
            if (widget == null || !openingDetails && widget.isHidden()) {
                continue;
            }
            Rectangle bounds = widget.getBounds();
            if (state.recommends(task)) {
                drawing.draw(bounds);
            }
            if (!openingDetails && bounds.contains(mouse.getX(), mouse.getY())) {
                tooltips.add(new Tooltip(details(task, state.courierPlan)));
            }
        }
        if (!openingDetails && plugin.getNoticeboard().getOffers().stream().noneMatch(state::recommends)) {
            String message = state.route.stops.isEmpty()
                    ? "No suitable courier offers"
                    : state.nextPort() == plugin.getNoticeboard().getPort()
                            ? "Close the board and complete the dock actions"
                            : "Continue to " + state.nextPort().name;
            Rectangle bounds = client.getWidget(InterfaceID.PortTaskBoard.FRAME).getBounds();
            drawing.setFont(FontManager.getRunescapeSmallFont());
            OverlayUtil.renderTextLocation(
                    drawing,
                    new Point(
                            bounds.x + (bounds.width - drawing.getFontMetrics().stringWidth(message)) / 2,
                            bounds.y + bounds.height - 11),
                    message,
                    Color.WHITE);
        }
        drawing.dispose();
        return null;
    }

    private boolean visible(int component) {
        Widget widget = client.getWidget(component);
        return widget != null && !widget.isHidden();
    }

    private boolean selected(CourierPlan plan, CourierTask task) {
        return plan != null && plan.selectedOffers.stream().anyMatch(offer -> offer.id == task.id);
    }

    private String details(CourierTask task, CourierPlan plan) {
        StringBuilder text = new StringBuilder(task.name);
        text.append("<br>").append(task.pickup.name).append(" to ").append(task.delivery.name);
        text.append(
                task.experience < 0
                        ? "<br>xp unavailable"
                        : String.format(Locale.ENGLISH, "<br>%,d courier xp (base)", task.experience));
        if (selected(plan, task)) {
            text.append("<br>Selected for the current route");
            text.append(String.format(Locale.ENGLISH, "<br>Plan: %,d courier xp", plan.courierExperience));
            if (!plan.selectedOffers.isEmpty()) {
                text.append("<br><br>Selected offers");
                for (CourierTask selected : plan.selectedOffers) {
                    text.append("<br>• ").append(selected.name);
                }
            }
        } else {
            text.append("<br>Not included in the current courier plan");
        }
        return text.toString();
    }
}

package com.harbourmaster.overlay;

import com.harbourmaster.HarbourmasterConfig;
import com.harbourmaster.HarbourmasterPlugin;
import com.harbourmaster.model.DockGuidance;
import com.harbourmaster.model.HarbourmasterSnapshot;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RouteLeg;
import com.harbourmaster.model.TravelStep;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Locale;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

public final class RouteStatusOverlay extends OverlayPanel {
    private final HarbourmasterPlugin plugin;
    private final HarbourmasterConfig config;

    @Inject
    public RouteStatusOverlay(HarbourmasterPlugin plugin, HarbourmasterConfig config) {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        panelComponent.setPreferredSize(new Dimension(245, 0));
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        HarbourmasterSnapshot state = plugin.getSnapshot();
        if (!plugin.isGuidanceActive() || !state.loggedIn || state.boardOpen) {
            return null;
        }
        panelComponent.getChildren().clear();
        DockGuidance guidance = plugin.getDockGuidance();
        if (guidance != DockGuidance.NONE && config.showDockChecklist()) {
            title(state.dock.port == null ? "Task cargo" : state.dock.port.name + " dock", config.activeRouteColor());
            line(guidance.instruction, guidance.unload ? config.unloadColor() : config.loadColor());
            line(guidance.detail, Color.WHITE);
        } else if (config.showRouteOverlay() && state.currentLeg != null && !state.currentLeg.sailingOnly()) {
            int next = state.currentLeg.steps.get(0).kind == TravelStep.Kind.SAIL
                            && state.currentLeg.steps.get(0).points.size() == 1
                    ? 1
                    : 0;
            TravelStep step = state.currentLeg.steps.get(next);
            title("Travel to " + state.nextPort().name, config.activeRouteColor());
            if (state.dock.port == null
                    && (step.kind == TravelStep.Kind.SUMMON || step.kind == TravelStep.Kind.CHARTER)) {
                line("Go to " + state.currentLeg.from.name + " dock", Color.WHITE);
            }
            line(step.instruction, Color.WHITE);
            if (state.currentLeg.steps.size() > next + 1) {
                line(state.currentLeg.steps.get(next + 1).instruction, Color.WHITE);
            }
            estimatedTravelTime(state.currentLeg);
        } else if (config.showRouteOverlay() && !state.route.stops.isEmpty()) {
            title(
                    state.currentLeg == null ? state.nextPort().name : "Travel to " + state.nextPort().name,
                    config.activeRouteColor());
            for (RouteEvent action : state.route.nextActions()) {
                line(action.description(), Color.WHITE);
            }
            if (state.currentLeg == null) {
                line(
                        state.dock.port == state.nextPort()
                                ? "Complete this stop before sailing"
                                : "Go to " + state.nextPort().name + " dock",
                        Color.WHITE);
            } else {
                estimatedTravelTime(state.currentLeg);
            }
        } else if (config.showRouteOverlay() && plugin.isCalculatingPlan()) {
            title("Updating route", config.activeRouteColor());
            line("Choosing the next courier actions", Color.LIGHT_GRAY);
        } else if (config.showRouteOverlay() && !state.route.available) {
            title("Route unavailable", config.activeRouteColor());
            line(state.route.reason, Color.LIGHT_GRAY);
        } else if (config.showRouteOverlay() && state.freeSlots > 0) {
            title("Check a noticeboard", config.activeRouteColor());
            line("Open the board to choose courier tasks", Color.WHITE);
        } else {
            return null;
        }
        return super.render(graphics);
    }

    private void estimatedTravelTime(RouteLeg leg) {
        long seconds = (long) Math.ceil(leg.travelTicks() * 0.6);
        line(
                String.format(Locale.ENGLISH, "Estimated travel: %dm %02ds", seconds / 60, seconds % 60),
                Color.LIGHT_GRAY);
    }

    private void title(String text, Color color) {
        panelComponent
                .getChildren()
                .add(TitleComponent.builder().text(text).color(color).build());
    }

    private void line(String text, Color color) {
        panelComponent
                .getChildren()
                .add(LineComponent.builder().left(text).leftColor(color).build());
    }
}

package com.harbourmaster.overlay;

import com.harbourmaster.HarbourmasterConfig;
import com.harbourmaster.HarbourmasterPlugin;
import com.harbourmaster.model.HarbourmasterSnapshot;
import com.harbourmaster.model.RouteLeg;
import com.harbourmaster.model.TravelStep;
import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.geom.Area;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.worldmap.WorldMapOverlay;

public final class WorldMapRouteOverlay extends Overlay {
    private final Client client;
    private final HarbourmasterPlugin plugin;
    private final HarbourmasterConfig config;
    private final WorldMapOverlay projection;

    @Inject
    public WorldMapRouteOverlay(
            Client client, HarbourmasterPlugin plugin, HarbourmasterConfig config, WorldMapOverlay projection) {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.projection = projection;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!plugin.isGuidanceActive()) {
            return null;
        }
        Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
        if (!config.showWorldMap()
                || map == null
                || map.isHidden()
                || client.getWorldMap().getWorldMapData() == null) {
            return null;
        }
        Graphics2D drawing = (Graphics2D) graphics.create();
        Area clip = new Area(map.getBounds());
        for (int component :
                new int[] {InterfaceID.Worldmap.OVERVIEW_CONTAINER, InterfaceID.Worldmap.MAPLIST_BOX_GRAPHIC0}) {
            Widget obstruction = client.getWidget(component);
            if (obstruction != null && !obstruction.isHidden()) {
                clip.subtract(new Area(obstruction.getBounds()));
            }
        }
        drawing.clip(clip);
        HarbourmasterSnapshot state = plugin.getSnapshot();
        List<RouteLeg> legs = state.route.legs;
        for (int index = legs.size() - 1; index >= 0; index--) {
            boolean current = legs.get(index) == state.currentLeg;
            if (!current && !config.showCompleteRoute()) {
                continue;
            }
            drawing.setColor(current ? config.activeRouteColor() : config.futureRouteColor());
            drawing.setStroke(new BasicStroke(current ? 3 : 1.5f));
            for (TravelStep step : legs.get(index).steps) {
                Point previous = null;
                for (WorldPoint point : step.points) {
                    Point canvas = projection.mapWorldPointToGraphicsPoint(point);
                    if (canvas != null && previous != null && step.kind == TravelStep.Kind.SAIL) {
                        NavigationOverlay.drawSegment(
                                drawing,
                                previous,
                                canvas,
                                Math.hypot(canvas.getX() - previous.getX(), canvas.getY() - previous.getY()) > 35);
                    }
                    if (canvas != null && step.kind != TravelStep.Kind.SAIL) {
                        drawing.drawOval(canvas.getX() - 4, canvas.getY() - 4, 8, 8);
                    }
                    previous = canvas;
                }
                if (previous != null) {
                    drawing.fillOval(previous.getX() - 3, previous.getY() - 3, 6, 6);
                    drawing.drawString(
                            step.kind == TravelStep.Kind.SAIL && legs.get(index).sailingOnly()
                                    ? legs.get(index).to.name
                                    : step.instruction,
                            previous.getX() + 7,
                            previous.getY());
                }
            }
        }
        drawing.dispose();
        return null;
    }
}

package com.harbourmaster.tracker;

import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.IntFunction;
import java.util.function.IntPredicate;
import java.util.function.IntUnaryOperator;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

public final class ActiveTaskTracker {
    private static final int[] CREW_CARGO_ITEMS = {
        VarPlayerID.SAILING_CREW_HELD_CARGO_0,
        VarPlayerID.SAILING_CREW_HELD_CARGO_1,
        VarPlayerID.SAILING_CREW_HELD_CARGO_2,
        VarPlayerID.SAILING_CREW_HELD_CARGO_3,
        VarPlayerID.SAILING_CREW_HELD_CARGO_4
    };
    private static final int[] CREW_CARGO_AMOUNTS = {
        VarbitID.SAILING_CREW_HELD_CARGO_0_AMOUNT,
        VarbitID.SAILING_CREW_HELD_CARGO_1_AMOUNT,
        VarbitID.SAILING_CREW_HELD_CARGO_2_AMOUNT,
        VarbitID.SAILING_CREW_HELD_CARGO_3_AMOUNT,
        VarbitID.SAILING_CREW_HELD_CARGO_4_AMOUNT
    };

    public List<ActiveTask> read(
            IntUnaryOperator varbit,
            IntUnaryOperator varplayer,
            IntFunction<CourierTask> catalog,
            IntPredicate ignoredTask,
            Port port) {
        List<ActiveTask> active = new ArrayList<>();
        for (int slot = 0; slot < TaskVarbits.IDS.length; slot++) {
            int id = varbit.applyAsInt(TaskVarbits.IDS[slot]);
            if (id == 0 || ignoredTask.test(id)) {
                continue;
            }
            active.add(new ActiveTask(
                    slot,
                    id,
                    catalog.apply(id),
                    varbit.applyAsInt(TaskVarbits.TAKEN[slot]),
                    varbit.applyAsInt(TaskVarbits.DELIVERED[slot])));
        }

        Map<Integer, Integer> crewCargo = new HashMap<>();
        for (int crew = 0; crew < CREW_CARGO_ITEMS.length; crew++) {
            int amount = varbit.applyAsInt(CREW_CARGO_AMOUNTS[crew]);
            if (amount > 0) {
                crewCargo.merge(varplayer.applyAsInt(CREW_CARGO_ITEMS[crew]), amount, Integer::sum);
            }
        }
        for (int index = 0; index < active.size(); index++) {
            ActiveTask task = active.get(index);
            if (task.definition == null || task.isFinished() || task.definition.pickup != port) {
                continue;
            }
            int carriedByCrew = crewCargo.getOrDefault(task.definition.itemId, 0);
            if (carriedByCrew > 0) {
                active.set(
                        index,
                        new ActiveTask(
                                task.slot,
                                task.taskId,
                                task.definition,
                                Math.min(task.definition.quantity, task.cargoTaken + carriedByCrew),
                                task.cargoDelivered));
            }
        }
        return List.copyOf(active);
    }

    public int occupiedSlots(IntUnaryOperator varbit) {
        int occupied = 0;
        for (int identifier : TaskVarbits.IDS) {
            if (varbit.applyAsInt(identifier) != 0) {
                occupied++;
            }
        }
        return occupied;
    }
}

package com.harbourmaster.tracker;

import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

public final class CargoTracker {
    public boolean needsDeposit(Client client, Map<Integer, Destination> destinations, Port dock) {
        Destination destination = carriedDestination(client, destinations);
        return destination != null && destination.port != dock;
    }

    public boolean needsUnload(Client client, Map<Integer, Destination> destinations) {
        return client.getLocalPlayer() != null
                && !client.getLocalPlayer().getWorldView().isTopLevel()
                && destinations.values().stream().anyMatch(destination -> destination.unload)
                && carriedDestination(client, destinations) == null;
    }

    public boolean carryingDelivery(Client client, Map<Integer, Destination> destinations) {
        Destination destination = carriedDestination(client, destinations);
        return destination != null && destination.unload;
    }

    private Destination carriedDestination(Client client, Map<Integer, Destination> destinations) {
        ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
        Item carried = equipment == null ? null : equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
        return carried == null ? null : destinations.get(carried.getId());
    }

    public Map<Integer, Destination> destinations(List<ActiveTask> tasks, Port dock) {
        Map<Integer, Destination> result = new HashMap<>();
        for (ActiveTask active : tasks) {
            if (active.definition == null || active.isFinished()) {
                continue;
            }
            CourierTask task = active.definition;
            result.put(task.itemId, new Destination(task.delivery, task.delivery == dock && active.carried() > 0));
        }
        return Map.copyOf(result);
    }

    public static final class Destination {
        public final Port port;
        public final boolean unload;

        private Destination(Port port, boolean unload) {
            this.port = port;
            this.unload = unload;
        }
    }
}

package com.harbourmaster.tracker;

import java.time.Instant;

public final class GuidanceActivityTracker {
    private Instant activeUntil = Instant.MIN;
    private boolean wasActive;

    public boolean update(boolean hasTasks, boolean browsingNoticeboard, Instant now) {
        boolean active = hasTasks || browsingNoticeboard;
        if (active || wasActive) {
            activeUntil = now.plusSeconds(60);
        }
        wasActive = active;
        return now.isBefore(activeUntil);
    }

    public void clear() {
        activeUntil = Instant.MIN;
        wasActive = false;
    }
}

package com.harbourmaster.tracker;

import com.harbourmaster.data.PortTaskCatalog;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

public final class NoticeboardTracker {
    private List<CourierTask> lastOffers = List.of();
    private Map<Integer, Widget> widgets = Map.of();
    private Port lastPort;
    private boolean openingDetails;
    private boolean detailsOpen;
    private boolean open;

    public void scan(Client client, PortTaskCatalog catalog) {
        Widget details = client.getWidget(InterfaceID.PortTaskInfo.WINDOW);
        if (details != null && !details.isHidden()) {
            openingDetails = false;
            detailsOpen = true;
            return;
        }
        if (openingDetails) {
            return;
        }
        detailsOpen = false;
        Widget container = client.getWidget(InterfaceID.PortTaskBoard.CONTAINER);
        open = container != null && !container.isHidden();
        if (!open) {
            widgets = Map.of();
            return;
        }
        Map<Integer, Widget> entries = new LinkedHashMap<>();
        List<CourierTask> offers = new ArrayList<>();
        Widget[] children = container.getDynamicChildren();
        if (children == null) {
            widgets = Map.of();
            lastOffers = List.of();
            lastPort = null;
            return;
        }
        for (Widget child : children) {
            Integer row = databaseRow(child == null ? null : child.getOnOpListener());
            if (row == null || entries.containsKey(row) || catalog.isIgnoredRow(row)) {
                continue;
            }
            CourierTask task = catalog.byRow(row);
            entries.put(row, child);
            offers.add(task);
        }
        widgets = Map.copyOf(entries);
        lastOffers = List.copyOf(offers);
        lastPort = offers.isEmpty() ? null : offers.get(0).board;
    }

    public static Integer databaseRow(Object[] listener) {
        return listener != null && listener.length > 3 && listener[3] instanceof Integer ? (Integer) listener[3] : null;
    }

    public void beginOpeningDetails(Widget widget) {
        if (widget != null) {
            Integer row = databaseRow(widget.getOnOpListener());
            if (row != null && widgets.containsKey(row)) {
                openingDetails = true;
            }
        }
    }

    public void clear() {
        lastOffers = List.of();
        widgets = Map.of();
        lastPort = null;
        openingDetails = false;
        detailsOpen = false;
        open = false;
    }

    public List<CourierTask> getOffers() {
        return lastOffers;
    }

    public Map<Integer, Widget> getWidgets() {
        return widgets;
    }

    public Port getPort() {
        return lastPort;
    }

    public boolean isOpen() {
        return open;
    }

    public boolean isDetailsOpen() {
        return detailsOpen;
    }

    public boolean isOpeningDetails() {
        return openingDetails;
    }
}

package com.harbourmaster.tracker;

import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

public final class OfferCycleTracker {
    private static final int TASKS_PER_OFFER_CYCLE = 8;
    private final Map<Port, List<CourierTask>> offersByPort = new EnumMap<>(Port.class);
    private int previousCompletedTasks = -1;
    private long resetDay = Long.MIN_VALUE;

    public void observe(int completedTasks, Port port, List<CourierTask> offers) {
        observe(completedTasks, port, offers, resetDay(Instant.now()));
    }

    public static long resetDay(Instant instant) {
        return LocalDate.ofInstant(instant, ZoneOffset.UTC).toEpochDay();
    }

    public void observe(int completedTasks, Port port, List<CourierTask> offers, long currentResetDay) {
        if (completedTasks / TASKS_PER_OFFER_CYCLE != previousCompletedTasks / TASKS_PER_OFFER_CYCLE
                || completedTasks < previousCompletedTasks
                || resetDay != currentResetDay) {
            offersByPort.clear();
        }
        previousCompletedTasks = completedTasks;
        resetDay = currentResetDay;
        if (port != null) {
            offersByPort.put(port, List.copyOf(offers));
        }
    }

    public Map<Port, List<CourierTask>> offers() {
        return Map.copyOf(offersByPort);
    }

    public boolean hasObservedOffers(Port port) {
        return offersByPort.containsKey(port);
    }

    public int tasksUntilReset() {
        return TASKS_PER_OFFER_CYCLE - previousCompletedTasks % TASKS_PER_OFFER_CYCLE;
    }

    public void clear() {
        offersByPort.clear();
        previousCompletedTasks = -1;
        resetDay = Long.MIN_VALUE;
    }
}

package com.harbourmaster.tracker;

import com.harbourmaster.data.BoatSize;
import com.harbourmaster.data.CargoHoldObjects;
import com.harbourmaster.model.Port;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.VarbitID;

public final class PortTracker {
    private static final int DOCK_APPROACH_DISTANCE = 5;
    private final Set<TileObject> objects = new HashSet<>();
    private Port dock;
    private Port associated;
    private Port start;
    private WorldPoint boatPosition;
    private boolean atSea;
    private BoatSize boatSize = BoatSize.SLOOP;

    public void add(TileObject object) {
        if (Port.fromObject(object.getId()) != null
                || CargoHoldObjects.IDS.contains(object.getId())
                || object.getId() == ObjectID.SAILING_GANGPLANK_PROXY) {
            objects.add(object);
        }
    }

    public void remove(TileObject object) {
        objects.remove(object);
    }

    public void unload(WorldView view) {
        objects.removeIf(object -> object.getWorldView() == view);
    }

    public void scanScene(Client client) {
        objects.clear();
        WorldView top = client.getTopLevelWorldView();
        if (top == null) {
            return;
        }
        scan(top);
        for (WorldEntity entity : top.worldEntities()) {
            scan(entity.getWorldView());
        }
    }

    private void scan(WorldView view) {
        if (view == null) {
            return;
        }
        for (Tile[][] plane : view.getScene().getTiles()) {
            for (Tile[] column : plane) {
                for (Tile tile : column) {
                    if (tile == null) {
                        continue;
                    }
                    if (tile.getGroundObject() != null) {
                        add(tile.getGroundObject());
                    }
                    for (GameObject object : tile.getGameObjects()) {
                        if (object != null) {
                            add(object);
                        }
                    }
                }
            }
        }
    }

    public void update(Client client, Port board) {
        dock = null;
        atSea = client.getVarbitValue(VarbitID.SAILING_TRANSMIT_IS_AT_SEA) != 0;
        WorldPoint location = position(client);
        updateBoatSize(client, location);
        if (location == null && board == null) {
            return;
        }
        boolean aboard = client.getLocalPlayer() != null
                && !client.getLocalPlayer().getWorldView().isTopLevel();
        boatPosition = aboard && board == null ? position(client, true) : null;
        int closestObject = 25;
        for (TileObject object : objects) {
            Port port = Port.fromObject(object.getId());
            if (location == null || port == null || !object.getWorldView().isTopLevel()) {
                continue;
            }
            int approachDistance =
                    boatPosition == null ? Integer.MAX_VALUE : boatPosition.distanceTo(port.navigationLocation);
            if (atSea && aboard && approachDistance > DOCK_APPROACH_DISTANCE) {
                continue;
            }
            int distance = approachDistance <= DOCK_APPROACH_DISTANCE
                    ? approachDistance
                    : location.distanceTo(WorldPoint.fromLocalInstance(client, object.getLocalLocation()));
            if (distance < closestObject) {
                closestObject = distance;
                dock = port;
            }
        }
        if (dock != null) {
            associated = dock;
        }
        if (board != null) {
            start = board;
            associated = board;
        } else if (dock != null) {
            start = dock;
        } else if (associated != null) {
            start = associated;
        } else {
            int nearest = 257;
            start = null;
            for (Port port : Port.values()) {
                int distance = location.distanceTo(port.navigationLocation);
                if (distance < nearest) {
                    nearest = distance;
                    start = port;
                }
            }
            if (atSea || aboard) {
                associated = start;
            }
        }
    }

    private void updateBoatSize(Client client, WorldPoint location) {
        Player player = client.getLocalPlayer();
        if (player == null) {
            return;
        }
        WorldView playerView = player.getWorldView();
        if (!playerView.isTopLevel()) {
            for (TileObject object : objects) {
                if (CargoHoldObjects.IDS.contains(object.getId()) && object.getWorldView() == playerView) {
                    boatSize = CargoHoldObjects.boatSizeForObject(object.getId());
                    return;
                }
            }
            return;
        }
        if (location == null) {
            return;
        }

        TileObject closestBoat = null;
        int closestDistance = 4;
        for (TileObject object : objects) {
            if (!CargoHoldObjects.IDS.contains(object.getId()) || object.getWorldView() != playerView) {
                continue;
            }
            int distance = location.distanceTo(WorldPoint.fromLocalInstance(client, object.getLocalLocation()));
            if (distance < closestDistance) {
                closestDistance = distance;
                closestBoat = object;
            }
        }
        if (closestBoat != null) {
            boatSize = CargoHoldObjects.boatSizeForObject(closestBoat.getId());
        }
    }

    public static WorldPoint position(Client client) {
        return position(client, false);
    }

    private static WorldPoint position(Client client, boolean boatAnchor) {
        Player player = client.getLocalPlayer();
        WorldView top = client.getTopLevelWorldView();
        if (player == null || top == null) {
            return null;
        }
        LocalPoint location = player.getLocalLocation();
        if (!player.getWorldView().isTopLevel()) {
            WorldEntity entity =
                    top.worldEntities().byIndex(player.getWorldView().getId());
            if (entity == null) {
                return null;
            }
            location = boatAnchor ? entity.getLocalLocation() : entity.transformToMainWorld(location);
        }
        return WorldPoint.fromLocalInstance(client, location);
    }

    public void clear() {
        objects.clear();
        dock = null;
        associated = null;
        start = null;
        boatPosition = null;
        atSea = false;
        boatSize = BoatSize.SLOOP;
    }

    public List<TileObject> getObjects() {
        return List.copyOf(objects);
    }

    public Port getDock() {
        return dock;
    }

    public boolean isAtSea() {
        return atSea;
    }

    public WorldPoint getBoatPosition() {
        return boatPosition;
    }

    public BoatSize getBoatSize() {
        return boatSize;
    }

    public Port getStart() {
        return start;
    }
}

package com.harbourmaster.tracker;

import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RoutePlan;
import com.harbourmaster.model.RouteStop;
import com.harbourmaster.optimizer.RouteOptimizer;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

public final class RouteTracker {
    private final RouteOptimizer optimizer;
    private RouteStop pendingStop;
    private RoutePlan previousPlan;
    private List<ActiveTask> previousTasks = List.of();

    public RouteTracker(RouteOptimizer optimizer) {
        this.optimizer = optimizer;
    }

    public RoutePlan update(Port start, List<ActiveTask> tasks) {
        return update(start, null, tasks);
    }

    public RoutePlan update(Port start, WorldPoint boatPosition, List<ActiveTask> tasks) {
        if (previousPlan != null && previousPlan.available && tasks.equals(previousTasks)) {
            RoutePlan relocated = optimizer.relocate(previousPlan, start, boatPosition);
            if (relocated.available) {
                previousPlan = relocated;
            }
            return relocated;
        }
        if (tasks.stream().anyMatch(task -> previousTasks.stream()
                .noneMatch(previous -> previous.slot == task.slot && previous.taskId == task.taskId))) {
            pendingStop = null;
        }
        Port firstStop = pendingStop != null && pendingStop.events.stream().anyMatch(event -> pending(event, tasks))
                ? pendingStop.port
                : null;
        RoutePlan route = optimizer.optimize(start, boatPosition, tasks, firstStop);
        previousTasks = List.copyOf(tasks);
        if (route.available) {
            pendingStop = route.stops.isEmpty() ? null : route.stops.get(0);
        }
        previousPlan = route;
        return route;
    }

    private static boolean pending(RouteEvent event, List<ActiveTask> tasks) {
        for (ActiveTask task : tasks) {
            if (task.slot == event.slot && task.taskId == event.task.id) {
                return task.definition == null
                        || (event.action == RouteEvent.Action.PICKUP
                                        ? task.pickupRemaining()
                                        : task.deliveryRemaining())
                                > 0;
            }
        }
        return false;
    }

    public void clear() {
        pendingStop = null;
        previousPlan = null;
        previousTasks = List.of();
    }
}

