        assertTrue(new RouteOptimizer(line()).optimize(A, tasks).available);
        entries = new Widget[] {entry(new Object[] {1, 2, 3, 8664}), entry(new Object[] {1, 2, 3, 99998})};
        NoticeboardTracker board = new NoticeboardTracker();
