    private static SailingPathfinder pathfinder(int minX, int maxX, int minY, int maxY, Map<Integer, byte[]> regions) {
        return new SailingPathfinder(new MemoryIndex(regions), minX, maxX, minY, maxY);
    }

    private static void assertSailableHeadings(RouteLeg route) {
        for (int index = 1; index < route.points.size(); index++) {
            int horizontal =
                    route.points.get(index).getX() - route.points.get(index - 1).getX();
            int vertical =
                    route.points.get(index).getY() - route.points.get(index - 1).getY();
            assertTrue(horizontal == 0 || vertical == 0 || Math.abs(horizontal) == Math.abs(vertical));
        }
    }

    private static byte[] terrain(int regionX, int regionY, int minX, int maxX, int minY, int maxY, Set<Long> land) {
        return terrain(regionX, regionY, minX, maxX, minY, maxY, land, Map.of(), Set.of());
    }

    private static byte[] terrain(
            int regionX,
            int regionY,
            int minX,
            int maxX,
            int minY,
            int maxY,
            Set<Long> land,
            Map<Long, Integer> attributes,
            Set<Long> docks) {
        try {
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            DataOutputStream output = new DataOutputStream(bytes);
            for (int plane = 0; plane < 4; plane++) {
                for (int x = 0; x < 64; x++) {
                    for (int y = 0; y < 64; y++) {
                        int worldX = regionX * 64 + x;
                        int worldY = regionY * 64 + y;
                        boolean water = plane == 0
                                && worldX >= minX
                                && worldX <= maxX
                                && worldY >= minY
                                && worldY <= maxY
                                && !land.contains(tile(worldX, worldY));
                        if (water) {
                            output.writeShort(2);
                            output.writeShort(454);
                        }
                        Integer attribute = attributes.get(tile(worldX, worldY));
                        if (plane == 0 && attribute != null) {
                            output.writeShort(attribute);
                            if (attribute <= 49) {
                                output.writeShort(454);
                            }
                        }
                        if (plane == 1 && docks.contains(tile(worldX, worldY))) {
                            output.writeShort(51);
                        }
                        output.writeShort(0);
                    }
                }
            }
            output.flush();
            return bytes.toByteArray();
        } catch (IOException exception) {
            throw new AssertionError(exception);
        }
    }

    private static long tile(int x, int y) {
        return (long) x << 32 | y & 0xffffffffL;
    }

    private static WorldPoint point(int x, int y) {
        return new WorldPoint(x, y, 0);
    }

    private static double measuredDistance(List<WorldPoint> points) {
        double distance = 0;
        for (int index = 1; index < points.size(); index++) {
            WorldPoint from = points.get(index - 1);
            WorldPoint to = points.get(index);
            distance += Math.hypot(to.getX() - from.getX(), to.getY() - from.getY());
        }
        return distance;
    }

    private static final class MemoryIndex implements IndexDataBase {
        private final Map<Integer, byte[]> regions;
        private final AtomicReference<Thread> indexThread;

        private MemoryIndex(Map<Integer, byte[]> regions) {
            this(regions, null);
        }

        private MemoryIndex(Map<Integer, byte[]> regions, AtomicReference<Thread> indexThread) {
            this.regions = regions;
            this.indexThread = indexThread;
        }

        @Override
        public boolean isOverlayOutdated() {
            return false;
        }

        @Override
        public int[] getFileIds(int archiveId) {
            return regions.containsKey(archiveId) ? new int[] {0} : new int[0];
        }

        @Override
        public byte[] loadData(int archiveID, int fileID) {
            if (indexThread != null) {
                indexThread.set(Thread.currentThread());
            }
            return fileID == 0 ? regions.get(archiveID) : null;
        }
    }
}

package com.harbourmaster.optimizer;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.data.PortGraph;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierPlan;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RouteLeg;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import org.junit.Test;

public class CourierCyclePlannerTest {
    private final RouteOptimizer optimizer = new RouteOptimizer(line());
    private final CourierCyclePlanner planner = new CourierCyclePlanner(optimizer);

    @Test
    public void overlappingObservedTasksCanBeatTheBestSingleTaskByCourierXpPerHour() {
        CourierTask outbound = courier(1, B, D, 300);
        CourierTask returnTask = courier(2, D, B, 300);

        CourierPlan plan = planner.plan(A, null, List.of(), Map.of(A, List.of(outbound, returnTask)), 99, 2, 8);
        CourierPlan single = planner.plan(A, null, List.of(), Map.of(A, List.of(outbound)), 99, 2, 8);

        assertEquals(Set.of(outbound, returnTask), Set.copyOf(plan.selectedOffers));
        assertEquals(600, plan.courierExperience);
        assertTrue(plan.experiencePerHour > single.experiencePerHour);
        assertInOrder(plan, outbound, RouteEvent.Action.ACCEPT, RouteEvent.Action.PICKUP, RouteEvent.Action.DELIVER);
        assertInOrder(plan, returnTask, RouteEvent.Action.ACCEPT, RouteEvent.Action.PICKUP, RouteEvent.Action.DELIVER);
    }

    @Test
    public void aKnownOfferCanUseOneSlotReleasedByAHeldDelivery() {
        CourierTask held = courier(1, A, B, 100);
        CourierTask observed = new CourierTask(2, 2, "Return task", 1, B, 102, "Cargo 2", 3, 1000, A, B);
        List<ActiveTask> tasks = List.of(loaded(held));

        CourierPlan plan = planner.plan(A, null, tasks, Map.of(B, List.of(observed)), 99, 0, 8);

        assertEquals(List.of(observed), plan.selectedOffers);
        List<RouteEvent> events =
                plan.route.stops.stream().flatMap(stop -> stop.events.stream()).collect(Collectors.toList());
        assertTrue(index(events, held, RouteEvent.Action.DELIVER) < index(events, observed, RouteEvent.Action.ACCEPT));
    }

    @Test
    public void fullSlotsWithoutAKnownHeldDeliveryDoNotAssumeAFutureSlot() {
        CourierTask observed = courier(1, B, D, 1000);

        CourierPlan plan = planner.plan(A, null, List.of(), Map.of(A, List.of(observed)), 99, 0, 8);

        assertTrue(plan.selectedOffers.isEmpty());
        assertEquals(0, plan.courierExperience);
    }

    @Test
    public void heldLevelGatedAndUnknownRewardTasksAreNotAddedAsOffers() {
        CourierTask held = courier(1, B, D, 100);
        CourierTask levelGated = new CourierTask(2, 2, "High level", 99, A, 102, "Cargo 2", 3, 10000, A, B);
        CourierTask unknownReward = courier(3, B, D, -1);
        CourierTask eligible = courier(4, B, D, 500);

        CourierPlan plan = planner.plan(
                A,
                null,
                List.of(accepted(held)),
                Map.of(A, List.of(held, levelGated, unknownReward, eligible)),
                50,
                2,
                8);

        assertEquals(List.of(eligible), plan.selectedOffers);
    }

    @Test
    public void sequentialTasksReuseOneSlotWithoutAcceptingBeforeDelivery() {
        CourierTask outward = courier(1, A, B, 500);
        CourierTask onward = new CourierTask(2, 2, "Onward", 1, B, 102, "Cargo", 3, 1000, B, D);
        CourierPlan plan = planner.plan(A, null, List.of(), Map.of(A, List.of(outward), B, List.of(onward)), 99, 1, 8);

        assertEquals(Set.of(outward, onward), Set.copyOf(plan.selectedOffers));
        int occupied = 0;
        for (RouteEvent event :
                plan.route.stops.stream().flatMap(stop -> stop.events.stream()).collect(Collectors.toList())) {
            if (event.action == RouteEvent.Action.ACCEPT) {
                occupied++;
            }
            if (event.action == RouteEvent.Action.DELIVER) {
                occupied--;
            }
            assertTrue(occupied >= 0 && occupied <= 1);
        }
        assertEquals(0, occupied);
    }

    @Test
    public void sharedCrossingCanWinEvenWhenBothOffersFallOutsideTheTopFiveSingles() {
        PortGraph graph = new PortGraph((from, to, size) -> Optional.of(new RouteLeg(
                        null,
                        null,
                        (from.equals(A.navigationLocation)
                                        ? 0
                                        : from.equals(Port.LUNAR_ISLE.navigationLocation) ? 160 : 100)
                                + (to.equals(A.navigationLocation)
                                        ? 0
                                        : to.equals(Port.LUNAR_ISLE.navigationLocation) ? 160 : 100),
                        List.of(from, to))))
                .detachedSnapshot(null);
        List<CourierTask> offers = new ArrayList<>();
        for (Port port : List.of(B, C, D, E, Port.PANDEMONIUM)) {
            offers.add(courier(offers.size() + 1, A, port, 100));
        }
        CourierTask first = courier(6, A, Port.LUNAR_ISLE, 140);
        CourierTask second = courier(7, A, Port.LUNAR_ISLE, 140);
        offers.add(first);
        offers.add(second);

        CourierPlan plan = new CourierCyclePlanner(new RouteOptimizer(graph))
                .plan(A, null, List.of(), Map.of(A, offers), 99, 2, 8);

        assertEquals(Set.of(first, second), Set.copyOf(plan.selectedOffers));
        assertEquals(
                Set.of(first, second),
                plan.route.nextActions().stream().map(event -> event.task).collect(Collectors.toSet()));
    }

    @Test
    public void lowRateKnownOfferDoesNotDisplaceAFasterHeldRoute() {
        CourierTask held = courier(1, B, D, 10000);
        CourierTask distantLowReward = new CourierTask(2, 2, "Distant delivery", 1, E, 102, "Cargo 2", 3, 1, C, E);

        CourierPlan plan =
                planner.plan(A, null, List.of(accepted(held)), Map.of(E, List.of(distantLowReward)), 99, 1, 8);

        assertTrue(plan.selectedOffers.isEmpty());
        assertEquals(10000, plan.courierExperience);
    }

    @Test
    public void offersToPortsWithoutBoardsAreExcludedWhileHeldCargoStillGetsDelivered() {
        CourierTask held = courier(1, A, Port.PISCATORIS, 1);
        CourierTask noBoard = courier(2, A, Port.PISCATORIS, 1000000);
        CourierTask boardDestination = courier(3, B, D, 1000);

        CourierPlan plan =
                planner.plan(A, null, List.of(loaded(held)), Map.of(A, List.of(noBoard, boardDestination)), 99, 1, 8);

        assertEquals(List.of(boardDestination), plan.selectedOffers);
        assertTrue(plan.route.stops.stream()
                .flatMap(stop -> stop.events.stream())
                .anyMatch(event -> event.task == held && event.action == RouteEvent.Action.DELIVER));
    }

    private static void assertInOrder(
            CourierPlan plan,
            CourierTask task,
            RouteEvent.Action first,
            RouteEvent.Action second,
            RouteEvent.Action third) {
        List<RouteEvent> events =
                plan.route.stops.stream().flatMap(stop -> stop.events.stream()).collect(Collectors.toList());
        assertTrue(index(events, task, first) < index(events, task, second));
        assertTrue(index(events, task, second) < index(events, task, third));
    }

    private static int index(List<RouteEvent> events, CourierTask task, RouteEvent.Action action) {
        for (int index = 0; index < events.size(); index++) {
            RouteEvent event = events.get(index);
            if (event.task == task && event.action == action) {
                return index;
            }
        }
        return Integer.MAX_VALUE;
    }
}

package com.harbourmaster.optimizer;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.data.PortGraph;
import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.Port;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RouteLeg;
import com.harbourmaster.model.RoutePlan;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Random;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class RouteOptimizerTest {
    private final RouteOptimizer optimizer = new RouteOptimizer(line());

    @Test
    public void singleTaskReconstructsPickupDeliveryAndTravelDistance() {
        RoutePlan plan = optimizer.optimize(A, List.of(accepted(courier(1, B, D, 100))));
        assertEquals(30, plan.distance, 0.00001);
        assertEquals(List.of(RouteEvent.Action.PICKUP, RouteEvent.Action.DELIVER), actions(plan));
        assertEquals(List.of(B, D), ports(plan));
        assertEquals(
                plan.distance,
                plan.legs.stream().mapToDouble(leg -> leg.distance).sum(),
                0.00001);
    }

    @Test
    public void cannotDeliverBeforePickupEvenWhenStandingAtDelivery() {
        RoutePlan plan = optimizer.optimize(A, List.of(accepted(courier(1, D, A, 100))));
        assertEquals(List.of(D, A), ports(plan));
        assertEquals(60, plan.distance, 0.00001);
    }

    @Test
    public void fullyLoadedCargoNeedsOnlyImmediateDelivery() {
        RoutePlan plan = optimizer.optimize(A, List.of(loaded(courier(1, D, A, 100))));
        assertEquals(0, plan.distance, 0);
        assertEquals(List.of(RouteEvent.Action.DELIVER), actions(plan));
        assertTrue(plan.legs.isEmpty());
    }

    @Test
    public void pickupAndDeliveryAtSamePortDoNotCauseReturnTrip() {
        RoutePlan plan =
                optimizer.optimize(A, List.of(accepted(courier(1, A, B, 100)), accepted(courier(2, B, D, 100))));
        assertEquals(30, plan.distance, 0.00001);
        assertEquals(
                List.of(A, B, D), plan.stops.stream().map(stop -> stop.port).collect(Collectors.toList()));
        assertEquals(2, plan.stops.get(1).events.size());
    }

    @Test
    public void partialProgressOnlyPlansOutstandingCratesAndSkipsCompletedTasks() {
        CourierTask task = courier(1, B, D, 100);
        RoutePlan plan = optimizer.optimize(
                A, List.of(new ActiveTask(0, 1, task, 2, 1), new ActiveTask(1, 2, courier(2, E, C, 100), 3, 3)));
        assertEquals(
                List.of(1, 2),
                plan.stops.stream()
                        .flatMap(stop -> stop.events.stream())
                        .map(event -> event.quantity)
                        .collect(Collectors.toList()));
    }

    @Test
    public void boardingTimeCanMakeASlightlyLongerSailingRouteFaster() {
        Map<WorldPoint, WorldPoint> positions = Map.of(
                A.navigationLocation, new WorldPoint(7, 14, 0),
                B.navigationLocation, new WorldPoint(17, 14, 0),
                C.navigationLocation, new WorldPoint(20, 5, 0),
                D.navigationLocation, new WorldPoint(17, 1, 0));
        PortGraph graph = new PortGraph((from, to, size) -> Optional.of(new RouteLeg(
                        null,
                        null,
                        Math.hypot(
                                positions.get(to).getX() - positions.get(from).getX(),
                                positions.get(to).getY() - positions.get(from).getY()),
                        List.of(from, to))))
                .detachedSnapshot(null);

        RoutePlan plan = new RouteOptimizer(graph)
                .optimize(
                        A,
                        List.of(
                                accepted(courier(1, B, D, 100)),
                                accepted(courier(2, B, D, 100)),
                                accepted(courier(3, C, B, 100))));

        assertEquals(
                List.of(C, B, D), plan.stops.stream().map(stop -> stop.port).collect(Collectors.toList()));
    }

    @Test
    public void optimumAgreesWithIndependentExhaustiveSearch() {
        Random random = new Random(20260921);
        Port[] ports = {A, B, C, D, E};
        for (int example = 0; example < 20; example++) {
            List<ActiveTask> tasks = new ArrayList<>();
            for (int id = 1; id <= 3; id++) {
                Port pickup = ports[random.nextInt(ports.length)];
                Port delivery = ports[random.nextInt(ports.length)];
                tasks.add(accepted(courier(id, pickup, delivery, 100)));
            }
            Port start = ports[random.nextInt(ports.length)];
            assertEquals(
                    brute(line(), start, tasks, new HashSet<>(), new HashSet<>()),
                    optimizer.optimize(start, tasks).legs.stream()
                            .mapToDouble(leg -> leg.distance / 4 + 2)
                            .sum(),
                    0.00001);
        }
    }

    private static double brute(
            PortGraph graph, Port from, List<ActiveTask> tasks, Set<Integer> picked, Set<Integer> delivered) {
        if (delivered.size() == tasks.size()) {
            return 0;
        }
        double best = Double.POSITIVE_INFINITY;
        for (ActiveTask active : tasks) {
            CourierTask task = active.definition;
            if (delivered.contains(task.id)) {
                continue;
            }
            boolean pickup = !picked.contains(task.id);
            Port destination = pickup ? task.pickup : task.delivery;
            Set<Integer> changed = pickup ? picked : delivered;
            changed.add(task.id);
            best = Math.min(
                    best,
                    graph.route(from, destination).get().distance / 4
                            + (from == destination ? 0 : 2)
                            + brute(graph, destination, tasks, picked, delivered));
            changed.remove(task.id);
        }
        return best;
    }

    private static List<Port> ports(RoutePlan plan) {
        return plan.stops.stream()
                .flatMap(stop -> stop.events.stream())
                .map(event -> event.port)
                .collect(Collectors.toList());
    }

    private static List<RouteEvent.Action> actions(RoutePlan plan) {
        return plan.stops.stream()
                .flatMap(stop -> stop.events.stream())
                .map(event -> event.action)
                .collect(Collectors.toList());
    }
}

