public class ActiveTaskTrackerTest {
    private final ActiveTaskTracker tracker = new ActiveTaskTracker();
    private final CourierTask courier = courier(1, A, D, 100);
    private final Map<Integer, Integer> varbits = new HashMap<>();
    private final Map<Integer, Integer> varplayers = new HashMap<>();
    private final Map<Integer, CourierTask> catalog = new HashMap<>(Map.of(1, courier));
    private Port port = A;

    @Test
    public void allFiveSlotsAreReadFreshAndLoginReplayCannotDuplicateThem() {
        assertTrue(read().isEmpty());
        for (int slot = 0; slot < 5; slot++) {
            varbits.put(TaskVarbits.IDS[slot], slot + 1);
            catalog.put(slot + 1, courier(slot + 1, A, D, 100));
        }
        List<ActiveTask> first = read();
        assertEquals(5, first.size());
        assertEquals(first, read());
        assertEquals(4, first.get(4).slot);
        varbits.put(TaskVarbits.IDS[1], 0);
        assertEquals(4, read().size());
    }

    @Test
    public void deliveredTaskOccupiesSlotUntilCleared() {
        progress(3, 3);
        assertEquals(1, tracker.occupiedSlots(id -> varbits.getOrDefault(id, 0)));
        varbits.put(TaskVarbits.IDS[0], 0);
        assertEquals(0, tracker.occupiedSlots(id -> varbits.getOrDefault(id, 0)));
    }

    @Test
    public void crewPickupUpdatesChecklistAndRouteBeforeDepositWithoutCountingTwice() {
        List<ActiveTask> beforePickup = List.of(progress(1, 0));
        assertEquals(2, DockChecklist.at(A, beforePickup).actions.get(0).quantity);

        varplayers.put(VarPlayerID.SAILING_CREW_HELD_CARGO_0, courier.itemId);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_0_AMOUNT, 1);
        assertEquals(1, DockChecklist.at(A, read()).actions.get(0).quantity);
        assertNotEquals(beforePickup, read());

        varplayers.put(VarPlayerID.SAILING_CREW_HELD_CARGO_1, courier.itemId);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_1_AMOUNT, 1);
        List<ActiveTask> withCrew = read();
        assertTrue(DockChecklist.at(A, withCrew).actions.isEmpty());
        RoutePlan route = new RouteOptimizer(line()).optimize(A, withCrew);
        assertEquals(
                List.of(RouteEvent.Action.DELIVER),
                route.stops.stream()
                        .flatMap(stop -> stop.events.stream())
                        .map(event -> event.action)
                        .collect(Collectors.toList()));
        varbits.put(TaskVarbits.TAKEN[0], 2);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_0_AMOUNT, 0);
        assertEquals(withCrew, read());
        varbits.put(TaskVarbits.TAKEN[0], 3);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_1_AMOUNT, 0);
        assertEquals(withCrew, read());
    }

    @Test
    public void crewCargoUsesQuantityAndItemIdentity() {
        progress(0, 0);
        varplayers.put(VarPlayerID.SAILING_CREW_HELD_CARGO_4, courier.itemId);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_4_AMOUNT, 2);
        assertEquals(1, DockChecklist.at(A, read()).actions.get(0).quantity);

        varplayers.put(VarPlayerID.SAILING_CREW_HELD_CARGO_4, courier(2, A, B, 100).itemId);
        assertEquals(3, DockChecklist.at(A, read()).actions.get(0).quantity);
    }

    @Test
    public void withdrawingCargoForPartialDeliveryDoesNotPretendMoreWasPickedUp() {
        progress(1, 0);
        port = D;
        varplayers.put(VarPlayerID.SAILING_CREW_HELD_CARGO_0, courier.itemId);
        varbits.put(VarbitID.SAILING_CREW_HELD_CARGO_0_AMOUNT, 1);
        assertEquals(2, read().get(0).pickupRemaining());
        assertEquals(1, DockChecklist.at(D, read()).actions.get(0).quantity);
    }

    private ActiveTask progress(int taken, int delivered) {
        varbits.put(TaskVarbits.IDS[0], 1);
        varbits.put(TaskVarbits.TAKEN[0], taken);
        varbits.put(TaskVarbits.DELIVERED[0], delivered);
        return read().get(0);
    }

    private List<ActiveTask> read() {
        return tracker.read(
                id -> varbits.getOrDefault(id, 0),
                id -> varplayers.getOrDefault(id, 0),
                catalog::get,
                id -> false,
                port);
    }
}

package com.harbourmaster.tracker;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.model.ActiveTask;
import com.harbourmaster.model.CourierTask;
import com.harbourmaster.model.DockChecklist;
import com.harbourmaster.model.RouteEvent;
import com.harbourmaster.model.RoutePlan;
import com.harbourmaster.optimizer.RouteOptimizer;
import java.util.List;
import java.util.Map;
import org.junit.Test;

public class CargoTrackerTest {
    @Test
    public void onlyCratesBoundForThisDockAreMarkedForUnloading() {
        CourierTask rum = courier(1, A, B, 100);
        CourierTask spice = courier(2, A, D, 100);
        Map<Integer, CargoTracker.Destination> cargo =
                new CargoTracker().destinations(List.of(loaded(rum), loaded(spice)), B);
        assertTrue(cargo.get(rum.itemId).unload);
        assertFalse(cargo.get(spice.itemId).unload);
        assertFalse(new CargoTracker().destinations(List.of(loaded(rum)), null).get(rum.itemId).unload);
    }

    @Test
    public void dockChecklistGroupsDeliveriesBeforeLoadsAndCountsOnlyAvailableCargo() {
        CourierTask partial = courier(1, A, B, 100);
        DockChecklist checklist = DockChecklist.at(
                B,
                List.of(
                        new ActiveTask(0, 1, partial, 2, 1),
                        loaded(courier(2, D, B, 100)),
                        accepted(courier(3, B, C, 100)),
                        accepted(courier(4, A, B, 100))));
        assertEquals(3, checklist.actions.size());
        assertEquals(RouteEvent.Action.DELIVER, checklist.actions.get(0).action);
        assertEquals(1, checklist.actions.get(0).quantity);
        assertEquals(RouteEvent.Action.DELIVER, checklist.actions.get(1).action);
        assertEquals(RouteEvent.Action.PICKUP, checklist.actions.get(2).action);
    }

    @Test
    public void unloadingStopsAsSoonAsThereIsRoomToAcceptBeforeTheBoardReset() {
        CourierTask first = courier(1, A, B, 100);
        CourierTask second = courier(2, A, B, 100);
        CourierTask offer = new CourierTask(3, 3, "Return task", 1, B, 103, "Cargo", 3, 1000, A, B);
        List<ActiveTask> held = List.of(loaded(first), loaded(second));
        RoutePlan route = new RouteOptimizer(line()).optimizeWithOffers(B, null, held, List.of(offer), 0, 2);
        DockChecklist dock = DockChecklist.at(B, held).follow(route);

        assertEquals(1, dock.actions.size());
        assertTrue(dock.unloads(first.itemId) != dock.unloads(second.itemId));
        CourierTask remaining = dock.unloads(first.itemId) ? second : first;
        held = List.of(loaded(remaining));
        route = new RouteOptimizer(line()).optimizeWithOffers(B, null, held, List.of(offer), 1, 1);
        dock = DockChecklist.at(B, held).follow(route);

        assertTrue(dock.hasAcceptance());
        assertFalse(dock.unloads(remaining.itemId));
    }
}

package com.harbourmaster.tracker;

import static com.harbourmaster.Fixtures.*;
import static org.junit.Assert.*;

import com.harbourmaster.model.CourierTask;
import java.time.Instant;
import java.util.List;
import org.junit.Test;

public class OfferCycleTrackerTest {
    @Test
    public void cachedOffersExpireAfterEightCompletedTasksAndAtDailyRollover() {
        OfferCycleTracker tracker = new OfferCycleTracker();
        CourierTask firstBoardOffer = courier(1, B, D, 100);
        CourierTask nextCycleOffer = new CourierTask(2, 2, "Task 2", 1, B, 102, "Cargo 2", 3, 100, A, D);
        long beforeMidnight = OfferCycleTracker.resetDay(Instant.parse("2026-09-23T22:59:59Z"));

        tracker.observe(7, A, List.of(firstBoardOffer), beforeMidnight);
        assertTrue(tracker.offers().containsKey(A));

        tracker.observe(8, B, List.of(nextCycleOffer), beforeMidnight);
        assertFalse(tracker.offers().containsKey(A));
        assertEquals(List.of(nextCycleOffer), tracker.offers().get(B));

        tracker.observe(0, A, List.of(firstBoardOffer), beforeMidnight);
        assertFalse(tracker.offers().containsKey(B));
        assertEquals(List.of(firstBoardOffer), tracker.offers().get(A));

        tracker.observe(0, null, List.of(), OfferCycleTracker.resetDay(Instant.parse("2026-09-23T23:00:00Z")));
        assertEquals(List.of(firstBoardOffer), tracker.offers().get(A));

        tracker.observe(
                0, B, List.of(nextCycleOffer), OfferCycleTracker.resetDay(Instant.parse("2026-09-24T00:00:00Z")));
        assertFalse(tracker.offers().containsKey(A));
        assertEquals(List.of(nextCycleOffer), tracker.offers().get(B));
    }

    @Test
    public void inspectingABoardWithoutCourierOffersReplacesItsOldOffersAndMarksItRead() {
        OfferCycleTracker tracker = new OfferCycleTracker();
        tracker.observe(0, A, List.of(courier(1, B, D, 100)), 0);

        tracker.observe(0, A, List.of(), 0);
        tracker.observe(0, null, List.of(), 0);

        assertTrue(tracker.hasObservedOffers(A));
        assertEquals(List.of(), tracker.offers().get(A));
    }
}

